    function getTroopTierInfo(lvl) {
      const level = Math.max(1, lvl || 1);
      const tiers = [
        { level: 1, name: '보병 (기본)', mult: 1.00, icon: '🛡️', nextName: 'Lv.2 숙련보병' },
        { level: 2, name: '숙련보병', mult: 1.15, icon: '🛡️', nextName: 'Lv.3 기마병' },
        { level: 3, name: '기마병', mult: 1.30, icon: '🐎', nextName: 'Lv.4 강궁병' },
        { level: 4, name: '강궁병', mult: 1.45, icon: '🏹', nextName: 'Lv.5 제갈연노병' },
        { level: 5, name: '제갈연노병', mult: 1.60, icon: '🎯', nextName: 'Lv.6 철갑전차병' },
        { level: 6, name: '철갑전차병', mult: 1.80, icon: '🛡️', nextName: 'Lv.7 호표기 돌격병' },
        { level: 7, name: '호표기 돌격기병', mult: 2.05, icon: '⚡', nextName: 'Lv.8 서량철기병' },
        { level: 8, name: '서량철기병', mult: 2.30, icon: '🏔️', nextName: 'Lv.9 천하무적군' }
      ];

      if (level <= 8) {
        const t = tiers[level - 1];
        return {
          level: level,
          typeName: t.name,
          mult: t.mult.toFixed(2),
          icon: t.icon,
          nextPromoText: t.nextName,
          reqExp: Math.min(250, 80 + (level - 1) * 20)
        };
      } else {
        // 9레벨 이상: 천하무적군 (신화 단계 - 무제한 레벨업 & 공방 배율 지속 강화)
        const mult = (2.30 + (level - 8) * 0.15).toFixed(2);
        return {
          level: level,
          typeName: '천하무적군',
          mult: mult,
          icon: '👑',
          nextPromoText: `Lv.${level + 1} 천하무적 극의 각성`,
          reqExp: Math.min(300, 150 + (level - 8) * 5)
        };
      }
    }

    function gainTroopExp(amount, reason = '') {
      if (gameState.troopExp === undefined) gameState.troopExp = 0;
      if (gameState.troopLevel === undefined) gameState.troopLevel = 1;

      gameState.troopExp += amount;
      if (reason) {
        logMessage(`🎖️ [경험치 획득] ${reason} (+${amount} EXP)`, 'text-yellow-300 font-bold');
      }

      let info = getTroopTierInfo(gameState.troopLevel);
      let leveledUp = false;

      // 누적 경험치로 폭풍 레벨업 가능!
      while (gameState.troopExp >= info.reqExp) {
        gameState.troopExp -= info.reqExp;
        gameState.troopLevel += 1;
        leveledUp = true;
        info = getTroopTierInfo(gameState.troopLevel);
        gameState.troopTypeName = info.typeName;

        logBattle(`🔥🎉 [전 부대 레벨업!] 치열한 실전 경험으로 전 부대 숙련도가 Lv.${gameState.troopLevel}(으)로 상승했습니다! (${info.typeName}, 공방 ${info.mult}배)`);
        logMessage(`🔥🎉 [전장 레벨업!] 전 부대 숙련도 Lv.${gameState.troopLevel} 달성! (${info.typeName}, 공방 ${info.mult}배)`, 'text-yellow-300 font-black');
        playSfx('victory');

        // 주요 승급 분기 축하 모달 (1~9레벨)
        if ([2, 3, 4, 5, 6, 7, 8, 9].includes(gameState.troopLevel)) {
          const tIcon = document.getElementById('promo-icon');
          const tTitle = document.getElementById('promo-title');
          const tDesc = document.getElementById('promo-desc');
          if (tIcon) tIcon.innerText = info.icon;
          if (tTitle) tTitle.innerText = `🎉 [병종 승급] ${info.typeName} 승급 달성!`;
          if (tDesc) tDesc.innerText = `병사들이 Lv.${gameState.troopLevel}에 도달하여 ${info.typeName}(으)로 전직했습니다! 공방 ${info.mult}배 대폭 강화!`;
          openModal('troop-promotion-modal');
        }
      }

      updateTroopLevelUI();
    }

    function updateTroopLevelUI() {
      const lvl = gameState.troopLevel || 1;
      const exp = gameState.troopExp || 0;
      const info = getTroopTierInfo(lvl);
      gameState.troopTypeName = info.typeName;

      // 우측 패널 UI 엘리먼트 매핑
      const tName = document.getElementById('troop-tier-name');
      const tBadge = document.getElementById('troop-tier-badge');
      const tMod = document.getElementById('troop-tier-mod');
      const tBar = document.getElementById('troop-exp-bar');
      const tText = document.getElementById('troop-exp-text');
      const tIcon = document.getElementById('troop-tier-icon');
      const tNext = document.getElementById('troop-next-promo-text'); // 🔥 핵심 버그 수정: 다음 승급 실시간 동적 갱신!

      if (tName) tName.innerText = info.typeName;
      if (tBadge) tBadge.innerText = `Lv. ${lvl}`;
      if (tMod) tMod.innerText = `공방 ${info.mult}배`;
      if (tBar) tBar.style.width = `${Math.min(100, (exp / info.reqExp) * 100)}%`;
      if (tText) tText.innerText = `경험치: ${exp} / ${info.reqExp} EXP`;
      if (tIcon) tIcon.innerText = info.icon;
      if (tNext) tNext.innerText = info.nextPromoText;

      // 하위 호환 매핑
      const pType = document.getElementById('panel-troop-type');
      const pLvl = document.getElementById('panel-troop-lvl');
      const pMult = document.getElementById('panel-troop-mult');
      if (pType) pType.innerText = info.typeName;
      if (pLvl) pLvl.innerText = `Lv. ${lvl}`;
      if (pMult) pMult.innerText = `공방 ${info.mult}배`;
    }

    function setDifficulty(level) {
      closeAllPopups();
      gameState.difficulty = level;
      updateDifficultyUI();
      playSfx('build');

      const names = {
        hard: '상급 (어려움 - 난세 패왕 모드)',
        normal: '중급 (보통 - 정통 실전 모드)',
        easy: '초급 (쉬움 - 초보자용 모드)'
      };

      logMessage(`⚔️ [레벨 설정] 게임레벨이 '${names[level]}'으로 설정되었습니다!`, level === 'hard' ? 'text-red-400 font-black' : 'text-yellow-300 font-bold');
      alert(`⚔️ 게임레벨이 [${names[level]}]으로 변경되었습니다!`);
    }

    function updateDifficultyUI() {
      const iconEl = document.getElementById('diff-badge-icon');
      const textEl = document.getElementById('diff-badge-text');
      const mapTag = document.getElementById('diff-map-tag');

      if (gameState.difficulty === 'hard') {
        iconEl.innerText = '🔥';
        textEl.innerText = '3. 게임레벨 : 상급';
        mapTag.innerText = '🔥 게임레벨 : 상급 (어려움 - 난세 패왕)';
        mapTag.className = 'bg-red-950/90 border border-red-500 px-2 py-0.5 rounded text-[11px] font-black text-yellow-300 shadow';
      } else if (gameState.difficulty === 'normal') {
        iconEl.innerText = '⚖️';
        textEl.innerText = '3. 게임레벨 : 중급';
        mapTag.innerText = '⚖️ 게임레벨 : 중급 (보통 - 정통 실전)';
        mapTag.className = 'bg-blue-950/90 border border-blue-400 px-2 py-0.5 rounded text-[11px] font-bold text-cyan-200 shadow';
      } else {
        iconEl.innerText = '🌱';
        textEl.innerText = '3. 게임레벨 : 초급';
        mapTag.innerText = '🌱 게임레벨 : 초급 (쉬움 - 초보자용)';
        mapTag.className = 'bg-emerald-950/90 border border-emerald-500 px-2 py-0.5 rounded text-[11px] font-bold text-emerald-300 shadow';
      }
    }

    // ==================== 팝업식 메뉴 토글 (100% 독립 드롭다운) ====================
    function togglePopup(e, id) {
      if (e) e.stopPropagation();
      const el = document.getElementById(id);
      if (!el) return;
      const isShow = el.classList.contains('show');
      closeAllPopups();
      if (!isShow) {
        el.classList.add('show');
      }
    }

    function closeAllPopups() {
      document.querySelectorAll('.koei-popup-window').forEach(w => w.classList.remove('show'));
    }

    document.addEventListener('click', function(e) {
      if (!e.target.closest('.menu-item-wrap')) {
        closeAllPopups();
      }
    });

    // 지도 핀 렌더링
    function renderMapPins() {
      // 13주 천하통일 즉시 감지 및 엔딩 자동 팝업
      const totalRulerProv = PROVINCES.filter(p => p.ruler === gameState.rulerName).length;
      if (totalRulerProv === 13) {
        setTimeout(() => {
          if (typeof openUnificationEnding === 'function') openUnificationEnding();
        }, 350);
      }

      const container = document.getElementById('map-pins-layer');
      container.innerHTML = '';

      PROVINCES.forEach(p => {
        const pin = document.createElement('div');
        pin.className = 'map-pin';
        pin.id = 'pin-' + p.id;
        pin.style.left = p.x + '%';
        pin.style.top = p.y + '%';

        const isMine = (p.ruler === gameState.rulerName);
        const isAlly = gameState.allies.includes(p.ruler);
        const isSelected = (p.id === gameState.selectedProvId);

        let badgeClass = 'bg-red-950/90 border-red-400 text-red-200';
        let icon = '⚔️';
        if (isMine) {
          badgeClass = 'bg-emerald-800 border-yellow-300 text-yellow-200';
          icon = '🚩';
        } else if (isAlly) {
          badgeClass = 'bg-sky-800 border-cyan-300 text-cyan-200';
          icon = '🤝';
        }
        if (isSelected) badgeClass += ' pin-selected ring-2 ring-yellow-400';

        pin.innerHTML = `
          <div class="pin-badge ${badgeClass}">
            <span>${icon}</span>
            <span>${p.id}. ${p.name}</span>
            <span class="text-[9px] opacity-80">(${p.ruler})</span>
          </div>
        `;
        pin.onclick = (e) => { e.stopPropagation(); selectProvince(p.id); };
        container.appendChild(pin);
      });
    }

    function selectProvince(provId) {
      gameState.selectedProvId = provId;
      renderMapPins();
      updateRightPanel(provId);
      const p = PROVINCES.find(x => x.id === provId);
      logMessage(`📍 [선택] ${p.id}. ${p.name} (${p.ruler} 영지, 방어력: ${p.defense})`, 'text-cyan-300');
      document.getElementById('prompt-text').innerText = `${p.id}. ${p.name} (${p.ruler})을 선택했습니다. 명령을 내리십시오.`;
    }

    // ==================== 👥 민충 100 달성 시 의용 지원병 8,000명 집결 시스템 ====================
    function checkMaxLoyaltyVolunteers(prov) {
      if (!prov || prov.ruler !== gameState.rulerName) return;
      if (prov.loyalty >= 100 && !prov.volunteersJoined) {
        prov.volunteersJoined = true;
        const rewardSoldiers = 8000;
        prov.soldiers += rewardSoldiers;
        playSfx('victory');

        logMessage(`🎉👥 [의용 지원병 8,000명 대거 집결!] ${prov.name}의 백성 충성도(민충)가 100(만점)을 달성하여, 주군의 높은 인덕에 감복한 정예 의용군 8,000명이 스스로 무기를 들고 자원입대했습니다! (병사: +8,000명)`, 'text-emerald-300 font-black text-sm animate-pulse');

        alert(`🎉👥 [선정의 결실 - 의용 지원병 8,000명 대거 집결!]\n\n${prov.name} 백성들의 민충(民忠)이 100(만점)에 도달했습니다!\n\n"유비 주군과 같은 어진 성군을 위해 목숨 바쳐 싸우겠습니다!"\n\n향토 청년들과 정예 의용군 8,000명이 스스로 무기를 들고 군에 자원입대하였습니다!\n\n▶ ${prov.name} 병력: +8,000명 대거 합류!\n▶ 현재 총 병력: ${prov.soldiers.toLocaleString()}명`);

        renderMapPins();
        updateRightPanel(prov.id);
      }
    }

    function updateRightPanel(provId) {
      updateActionPointUI();
      const p = PROVINCES.find(x => x.id === provId);
      if (!p) return;

      document.getElementById('map-selected-name').innerText = `${p.id}. ${p.name} (${p.ruler})`;
      document.getElementById('panel-city-title').innerText = `${p.id}. ${p.name}`;
      document.getElementById('panel-ruler-name').innerText = p.ruler;
      document.getElementById('panel-governor').innerText = p.leader;
      document.getElementById('panel-advisor').innerText = p.advisor;
      document.getElementById('panel-defense').innerText = p.defense;

      document.getElementById('val-pop').innerText = p.pop.toLocaleString();
      document.getElementById('val-gold').innerText = p.gold.toLocaleString();
      document.getElementById('val-food').innerText = p.food.toLocaleString();
      document.getElementById('val-sol').innerText = p.soldiers.toLocaleString();
      document.getElementById('val-off').innerText = p.officers;
      document.getElementById('val-loy').innerText = p.loyalty;

      document.getElementById('bar-pop').style.width = Math.min(100, (p.pop / 600000) * 100) + '%';
      document.getElementById('bar-gold').style.width = Math.min(100, (p.gold / 6000) * 100) + '%';
      document.getElementById('bar-food').style.width = Math.min(100, (p.food / 60000) * 100) + '%';
      document.getElementById('bar-sol').style.width = Math.min(100, (p.soldiers / 40000) * 100) + '%';
      document.getElementById('bar-off').style.width = Math.min(100, (p.officers / 20) * 100) + '%';
      document.getElementById('bar-loy').style.width = p.loyalty + '%';
      checkMaxLoyaltyVolunteers(p);

      const loyHintEl = document.getElementById('loyalty-volunteers-hint');
      if (loyHintEl) {
        if (p.ruler === gameState.rulerName) {
          if (p.volunteersJoined) {
            loyHintEl.innerHTML = '<span class="text-emerald-300 font-bold">✨ 민충 100 달성 완료 (의용군 8,000명 참전 완료)</span>';
          } else {
            loyHintEl.innerHTML = `<span class="text-amber-300 font-bold animate-pulse">💡 민충 100 달성 시: 정예 의용 지원병 8,000명 즉시 자원입대! (현재: ${p.loyalty}/100)</span>`;
          }
        } else {
          loyHintEl.innerHTML = '';
        }
      }

      // 12군주 초상화 및 공손찬 얼굴 실시간 정확 매핑
      updateRulerPortraitDisplay(p.ruler);

      document.getElementById('rate-rice-sell').innerText = gameState.rates.riceSell;
      document.getElementById('rate-rice-buy').innerText = gameState.rates.riceBuy;
      document.getElementById('rate-crossbow').innerText = gameState.rates.crossbow;
      document.getElementById('rate-heavy-bow').innerText = gameState.rates.heavyBow;
      document.getElementById('rate-horse').innerText = gameState.rates.horse;

      
      // 🔥 우측 패널 하단 원클릭 침공 / 출진 버튼 동적 렌더링
      const actionContainer = document.getElementById('panel-action-btn-container');
      if (actionContainer) {
        if (p.ruler !== gameState.rulerName) {
          actionContainer.innerHTML = `
            <button onclick="openWarModal(${p.id})" class="w-full py-2.5 bg-gradient-to-r from-red-700 via-amber-600 to-rose-700 hover:from-red-600 hover:to-rose-500 text-yellow-100 font-black text-xs rounded-lg border-2 border-yellow-300 shadow-2xl flex items-center justify-center gap-2 animate-pulse">
              <span>⚔️</span> ${p.id}. ${p.name} (${p.ruler}군) 침공작전 개시 (출전 장수 편성)
            </button>
          `;
        } else {
          actionContainer.innerHTML = `
            <button onclick="openWarTargetSelectModal()" class="w-full py-2 bg-gradient-to-r from-blue-800 to-indigo-800 hover:from-blue-700 hover:to-indigo-700 text-cyan-100 font-bold text-xs rounded border border-cyan-300 shadow flex items-center justify-center gap-1.5">
              <span>🚩</span> 인접 적 영지 침공 작전 개시
            </button>
          `;
        }
      }

      const storageStatusEl = document.getElementById('food-storage-status');
      if (storageStatusEl) {
        storageStatusEl.innerText = `내구 ${gameState.storageHp}% (${gameState.storageHp >= 50 ? '안전' : '위험'})`;
        storageStatusEl.className = gameState.storageHp >= 50 ? 'text-emerald-400 font-black' : 'text-red-400 font-black';
      }

      const myProvs = PROVINCES.filter(x => x.ruler === gameState.rulerName).length;
      document.getElementById('unify-progress').innerText = `${myProvs} / 13주 (${Math.round((myProvs / 13) * 100)}%)`;
      const myCountEl = document.getElementById('my-provinces-count');
      if (myCountEl) myCountEl.innerText = myProvs;

      // 오직 모든 영지가 0개가 되었을 때만 멸망!
      if (myProvs === 0) {
        alert('💀 적군에게 모든 본거지와 영지를 빼앗겨 천하의 뜻이 꺾였습니다! (보유 영지: 0개)');
        logMessage('💀 [천하 멸망] 모든 영지를 상실하여 군벌이 해체되었습니다.', 'text-red-500 font-black');
      }
    }

    // ==================== 12대 군주 초상화 완벽 매핑 (공손찬 100% 반영) ====================
