    // 3. 전장 그리드 및 지형 설정 (Odd-R Hex Grid)
    const GRID_COLS = 13;
    const GRID_ROWS = 8;
    const HEX_RADIUS = 46;
    const HEX_W = Math.sqrt(3) * HEX_RADIUS;
    const HEX_H = 2 * HEX_RADIUS;

    // 지형 매핑
    // 0: 평지, 1: 숲(화계 쉬움/방어+15%), 2: 산악, 3: 호로관 관문, 4: 적 군량 보급창(우측 상단 8, 3)
    let MAP_TERRAIN = Array.from({length: GRID_ROWS}, () => Array(GRID_COLS).fill(0));

    // 게임 상태
    let sam5BattleState = {
      turn: 1,
      maxTurns: MAX_TURNS,
      phase: "ally", // 'ally' or 'enemy'
      weather: "맑음",
      wind: "남동풍",
      selectedUnit: null,
      reachableHexes: [],
      attackableTargets: [],
      skillMode: null,
      soundEnabled: true,
      fireTiles: [{ q: 4, r: 2, turns: 3 }],
      supplyBurned: false, // 보급창 함락 여부
      battleOver: false,
      battleRhythmStreak: 0
    };

    // 일기토 상태
    let sam5DuelState = {
      p1: null, p2: null,
      p1Hp: 100, p2Hp: 100,
      round: 0
    };

    const canvas = document.getElementById("battleCanvas");
    const ctx = canvas.getContext("2d");

    // ==========================================================================
    // Web Audio 신디사이저
    // ==========================================================================
    let audioCtx = null;
    function getAudioContext() {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      return audioCtx;
    }

    function playSound(type) {
      if (!sam5BattleState.soundEnabled) return;
      try {
        const actx = getAudioContext();
        if (actx.state === 'suspended') actx.resume();

        const now = actx.currentTime;
        const osc = actx.createOscillator();
        const gain = actx.createGain();
        osc.connect(gain);
        gain.connect(actx.destination);

        if (type === 'slash') {
          osc.type = 'sawtooth';
          osc.frequency.setValueAtTime(500, now);
          osc.frequency.exponentialRampToValueAtTime(70, now + 0.16);
          gain.gain.setValueAtTime(0.45, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.16);
          osc.start(now);
          osc.stop(now + 0.16);
        } else if (type === 'arrow') {
          osc.type = 'sine';
          osc.frequency.setValueAtTime(900, now);
          osc.frequency.exponentialRampToValueAtTime(280, now + 0.2);
          gain.gain.setValueAtTime(0.3, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
          osc.start(now);
          osc.stop(now + 0.2);
        } else if (type === 'fire') {
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(140, now);
          osc.frequency.exponentialRampToValueAtTime(25, now + 0.4);
          gain.gain.setValueAtTime(0.55, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);
          osc.start(now);
          osc.stop(now + 0.4);
        } else if (type === 'fanfare') {
          osc.type = 'square';
          osc.frequency.setValueAtTime(349, now);
          osc.frequency.setValueAtTime(440, now + 0.09);
          osc.frequency.setValueAtTime(523, now + 0.18);
          gain.gain.setValueAtTime(0.25, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.35);
          osc.start(now);
          osc.stop(now + 0.35);
        } else if (type === 'drum') {
          osc.type = 'sine';
          osc.frequency.setValueAtTime(120, now);
          osc.frequency.exponentialRampToValueAtTime(30, now + 0.25);
          gain.gain.setValueAtTime(0.6, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);
          osc.start(now);
          osc.stop(now + 0.25);
        }
      } catch (e) {
        console.warn("Audio error:", e);
      }
    }

    function toggleSound() {
      sam5BattleState.soundEnabled = !sam5BattleState.soundEnabled;
      document.getElementById("soundLabel").innerText = sam5BattleState.soundEnabled ? "효과음 ON" : "효과음 OFF";
      document.getElementById("soundBtn").classList.toggle("opacity-50", !sam5BattleState.soundEnabled);
    }

    // ==========================================================================
    // 헥스 좌표 연산
    // ==========================================================================
    function getHexPixel(q, r) {
      const x = 58 + q * HEX_W + (r % 2 === 1 ? HEX_W / 2 : 0);
      const y = 48 + r * (HEX_H * 0.75);
      return { x, y };
    }

    function getHexDistance(q1, r1, q2, r2) {
      const x1 = q1 - (r1 - (r1 & 1)) / 2;
      const z1 = r1;
      const y1 = -x1 - z1;
      const x2 = q2 - (r2 - (r2 & 1)) / 2;
      const z2 = r2;
      const y2 = -x2 - z2;
      return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2), Math.abs(z1 - z2));
    }

    // 🎯 특정 사거리(range) 내의 적군 부대 목록 반환
    function getEnemiesInRange(unit, range) {
      if (!unit) return [];
      const enemyFaction = (unit.faction === 'ally') ? 'enemy' : 'ally';
      return UNITS.filter(target => {
        if (target.faction !== enemyFaction || target.troops <= 0) return false;
        const dist = getHexDistance(unit.q, unit.r, target.q, target.r);
        return dist <= range;
      });
    }

    function findUnitAt(q, r) {
      return UNITS.find(u => u.q === q && u.r === r && u.troops > 0);
    }

    // ==========================================================================
    // 캔버스 렌더링 시스템 (불길 확산 & 헥스 맵)
    // ==========================================================================
    function drawHexagon(ctx, x, y, radius, fillColor, strokeColor, lineWidth = 1) {
      ctx.beginPath();
      for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 180) * (60 * i - 30);
        const hx = x + radius * Math.cos(angle);
        const hy = y + radius * Math.sin(angle);
        if (i === 0) ctx.moveTo(hx, hy);
        else ctx.lineTo(hx, hy);
      }
      ctx.closePath();
      if (fillColor) {
        ctx.fillStyle = fillColor;
        ctx.fill();
      }
      if (strokeColor) {
        ctx.strokeStyle = strokeColor;
        ctx.lineWidth = lineWidth;
        ctx.stroke();
      }
    }

    function renderBattlefield() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // 1. 헥스 타일 렌더링
      for (let r = 0; r < GRID_ROWS; r++) {
        for (let q = 0; q < GRID_COLS; q++) {
          const { x, y } = getHexPixel(q, r);
          const terrain = MAP_TERRAIN[r][q];

          let tileColor = "#162032";
          let borderColor = "#334155";

          if (terrain === 1) tileColor = "#14532d"; // 숲
          else if (terrain === 2) tileColor = "#44403c"; // 산악
          else if (terrain === 3) tileColor = "#334155"; // 🧱 성벽 (석조 방벽)
          else if (terrain === 9) tileColor = "#78350f"; // ⛩️ 성문/관문
          else if (terrain === 4) tileColor = sam5BattleState.supplyBurned ? "#292524" : "#854d0e"; // 🌾 적 보급창
          else if (terrain === 8) tileColor = sam5BattleState.allySupplyBurned ? "#292524" : "#047857"; // 🌾 아군 보급창
          else if (terrain === 5) tileColor = "#1e3a8a"; // 강물/수로
          else if (terrain === 6) tileColor = "#4a044e"; // 늪지대/독천
          else if (terrain === 7) tileColor = "#b45309"; // 🏆 전설의 보물 상자

          // 이동/공격 하이라이트
          const isReachable = sam5BattleState.reachableHexes.some(h => h.q === q && h.r === r);
          if (isReachable) {
            tileColor = "#065f46";
            borderColor = "#34d399";
          }

          const isAttackable = sam5BattleState.attackableTargets.some(t => t.q === q && t.r === r);
          if (isAttackable) {
            tileColor = "#991b1b";
            borderColor = "#f87171";
          }

          const isBurning = sam5BattleState.fireTiles.some(f => f.q === q && f.r === r);
          if (isBurning) {
            tileColor = "#c2410c";
          }

          drawHexagon(ctx, x, y, HEX_RADIUS - 1, tileColor, borderColor, isReachable || isAttackable ? 2.5 : 1);

          // 지형 텍스트 라벨
          ctx.font = "bold 10px sans-serif";
          ctx.fillStyle = "rgba(255,255,255,0.45)";
          ctx.textAlign = "center";
          if (terrain === 1) ctx.fillText("🌲숲", x, y - 16);
          else if (terrain === 2) ctx.fillText("⛰️산", x, y - 16);
          else if (terrain === 3) {
            ctx.font = "bold 11px sans-serif";
            ctx.fillStyle = "#cbd5e1";
            ctx.fillText("🧱성벽", x, y - 14);
            ctx.font = "14px sans-serif";
            ctx.fillText("🛡️", x, y + 14);
          }
          else if (terrain === 9) {
            ctx.font = "bold 11px sans-serif";
            ctx.fillStyle = "#fde047";
            ctx.fillText("⛩️성문", x, y - 14);
            ctx.font = "14px sans-serif";
            ctx.fillText("🚪", x, y + 14);
          }
          else if (terrain === 4) {
            ctx.font = "bold 11px sans-serif";
            ctx.fillStyle = sam5BattleState.supplyBurned ? "#ef4444" : "#facc15";
            ctx.fillText(sam5BattleState.supplyBurned ? "💥적량고소실" : "🌾적군군량고", x, y - 16);
            ctx.font = "14px sans-serif";
            ctx.fillText(sam5BattleState.supplyBurned ? "🔥" : "🏯", x, y + 16);
          }
          else if (terrain === 8) {
            ctx.font = "bold 11px sans-serif";
            ctx.fillStyle = sam5BattleState.allySupplyBurned ? "#ef4444" : "#34d399";
            ctx.fillText(sam5BattleState.allySupplyBurned ? "💥아량고소실" : "🌾아군군량고", x, y - 16);
            ctx.font = "14px sans-serif";
            ctx.fillText(sam5BattleState.allySupplyBurned ? "🔥" : "🏰", x, y + 16);
          }

          if (isBurning) {
            ctx.font = "15px sans-serif";
            ctx.fillText("🔥", x, y + 18);
          }
        }
      }

      // 2. 부대 렌더링
      UNITS.forEach(unit => {
        if (unit.troops <= 0) return;
        const { x, y } = getHexPixel(unit.q, unit.r);
        const isSelected = sam5BattleState.selectedUnit && sam5BattleState.selectedUnit.id === unit.id;
        const isAlly = unit.faction === "ally";

        // 선택 하이라이트 원
        if (isSelected) {
          ctx.beginPath();
          ctx.arc(x, y, HEX_RADIUS - 4, 0, Math.PI * 2);
          ctx.strokeStyle = "#facc15";
          ctx.lineWidth = 3.5;
          ctx.stroke();
        }

        // 베이스 원형
        ctx.beginPath();
        ctx.arc(x, y, 27, 0, Math.PI * 2);
        ctx.fillStyle = isAlly ? "#1d4ed8" : (unit.isBoss ? "#7f1d1d" : "#b91c1c");
        ctx.fill();
        ctx.strokeStyle = unit.acted ? "#475569" : (isAlly ? "#93c5fd" : "#fca5a5");
        ctx.lineWidth = unit.isBoss ? 3 : 2;
        ctx.stroke();

        // 행동 완료 표시 음영
        if (unit.acted) {
          ctx.fillStyle = "rgba(0,0,0,0.5)";
          ctx.beginPath();
          ctx.arc(x, y, 27, 0, Math.PI * 2);
          ctx.fill();
        }

        // 아바타
        ctx.font = "24px serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(unit.avatar, x, y - 2);

        // 무장명
        ctx.font = "bold 13px sans-serif"; ctx.fillStyle = unit.isBoss ? "#fef08a" : "#ffffff"; ctx.shadowColor = "#000000"; ctx.shadowBlur = 5; ctx.fillText(unit.name, x, y + 17);
        ctx.shadowBlur = 0;

        // 삼국지 5 진형 배지 표시
        const formObj = FORMATIONS[unit.formation];
        if (formObj) {
          ctx.font = "bold 9px sans-serif";
          ctx.fillStyle = formObj.color;
          ctx.fillText(`[${formObj.name.substring(0, 2)}]`, x, y - 18);
        }

        // 병력 게이지
        const hpPercent = Math.max(0, unit.troops / unit.maxTroops);
        const barW = 46; const barH = 5; ctx.fillStyle = "#0f172a"; ctx.fillRect(x - barW / 2, y + 27, barW, barH);
        ctx.fillStyle = isAlly ? (hpPercent > 0.4 ? "#22c55e" : "#ef4444") : (unit.isBoss ? "#e11d48" : "#f97316");
        ctx.fillRect(x - barW / 2, y + 23, barW * hpPercent, barH);
      });
    }

    // ==========================================================================
    // 마우스 상호작용
    // ==========================================================================
        // ==========================================================================
    // 🎯 캔버스 정밀 히트테스트(Hit-Test) 및 직관적 원클릭 부대 공격 시스템
    // ==========================================================================
    canvas.addEventListener("click", function(e) {
      if (sam5BattleState.battleOver) return;
      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width;
      const scaleY = canvas.height / rect.height;
      const mx = (e.clientX - rect.left) * scaleX;
      const my = (e.clientY - rect.top) * scaleY;

      // 1. 가장 가까운 헥스 타일 찾기
      let closestHex = null;
      let minTileDist = 9999;
      for (let r = 0; r < GRID_ROWS; r++) {
        for (let q = 0; q < GRID_COLS; q++) {
          const { x, y } = getHexPixel(q, r);
          const dist = Math.hypot(mx - x, my - y);
          if (dist < minTileDist) {
            minTileDist = dist;
            closestHex = { q, r };
          }
        }
      }

      // 2. 해당 헥스에 위치한 유닛 또는 반경 42px 내 유닛 감지 (초정밀 타겟팅)
      let clickedUnit = null;
      if (closestHex && minTileDist < HEX_RADIUS * 1.25) {
        clickedUnit = findUnitAt(closestHex.q, closestHex.r);
      }
      if (!clickedUnit) {
        for (const u of UNITS) {
          if (u.troops <= 0) continue;
          const { x, y } = getHexPixel(u.q, u.r);
          const d = Math.hypot(mx - x, my - y);
          if (d < 42) {
            clickedUnit = u;
            break;
          }
        }
      }

      // 🎯 유닛을 클릭한 경우
      if (clickedUnit) {
        handleUnitClick(clickedUnit);
        return;
      }

      // 🎯 빈 타일을 클릭한 경우 (이동 또는 조준)
      if (closestHex && minTileDist < HEX_RADIUS * 1.25) {
        handleTileClick(closestHex.q, closestHex.r);
      }
    });

    // 🎯 유닛 클릭 핸들러: 아군 선택 / 적군 원클릭 즉시 공격
    // 🎯 원클릭 자동 공격 및 돌격 전담 실행기 (Direct Attack & Auto Charge)
    function executeDirectAttack(attacker, target) {
      if (!attacker || !target) return;
      const dist = getHexDistance(attacker.q, attacker.r, target.q, target.r);
      const isArcher = isMasterArcher(attacker);

      // Case 1: 인접 1칸 적 -> 즉시 칼을 뽑아 근접 공격 또는 3면 포위 일제합공!
      if (dist === 1) {
        logBattle("🗡️ [근접 공격] " + attacker.name + " 부대가 적장 " + target.name + "에게 돌격을 감행합니다!");
        executeSkillAction('attack', target);
        return;
      }

      // Case 2: 2~4칸 거리 적 -> 모든 장수 화살(궁시) 사격 또는 맹화시 발사!
      if (dist <= 4) {
        logBattle("🏹 [원거리 사격] " + attacker.name + " 부대가 적장 " + target.name + "에게 화살비를 쏟아붓습니다! (사거리 4칸)");
        executeSkillAction('archery', target);
        return;
      }

      // Case 3: 4칸 초과 거리 적 -> 적 인접 타일로 맹렬히 돌격 진격 후 공격!
      if (!attacker.moved) {
        computeMovementRange(attacker);
        if (sam5BattleState.reachableHexes.length > 0) {
          let bestHex = null;
          let bestDist = 999;
          sam5BattleState.reachableHexes.forEach(h => {
            const d = getHexDistance(h.q, h.r, target.q, target.r);
            if (d < bestDist) {
              bestDist = d;
              bestHex = h;
            }
          });

          if (bestHex) {
            attacker.q = bestHex.q;
            attacker.r = bestHex.r;
            attacker.moved = true;
            sam5BattleState.reachableHexes = [];
            playSound('fanfare');

            const newDist = getHexDistance(attacker.q, attacker.r, target.q, target.r);
            if (newDist === 1) {
              logBattle("🏇 [질풍 돌격!] " + attacker.name + " 부대가 적장 " + target.name + "에게 쇄도하여 통렬한 돌격을 가합니다!");
              executeSkillAction('attack', target);
            } else if (newDist <= 4) {
              logBattle("🏇🏹 [돌격 사격!] " + attacker.name + " 부대가 진격 후 적장 " + target.name + "에게 화살비를 쏟아붓습니다!");
              executeSkillAction('archery', target);
            } else {
              logBattle("🏇 " + attacker.name + " 부대가 적장 " + target.name + "을 향해 급속 돌격 진격했습니다!");
              updateActionCommands();
            }
            return;
          }
        }
      }

      logBattle("적장 " + target.name + "이 너무 멀어 공격이 닿지 않습니다. 먼저 녹색 이동 타일을 클릭하여 진격하십시오.");
    }

    function handleUnitClick(unit) {
      const selected = sam5BattleState.selectedUnit;

      // 특기/명령 조준 모드(화계, 원거리 조준 등)인 경우
      if (sam5BattleState.skillMode) {
        executeSkillAction(sam5BattleState.skillMode, unit);
        clearSkillMode();
        renderBattlefield();
        return;
      }

      // 아군 턴이 아니면 단순 카드 조회
      if (sam5BattleState.phase !== "ally") {
        selectUnit(unit);
        renderBattlefield();
        return;
      }

      // A. 아군 부대를 클릭한 경우 -> 선택 및 이동범위 활성화
      if (unit.faction === "ally") {
        selectUnit(unit);
        logBattle(`🛡️ 아군 [${unit.name}] 부대를 선택했습니다. 적 부대를 클릭하거나 [원클릭 즉시 공격]을 누르십시오!`);
        renderBattlefield();
        return;
      }

      // B. 적군 부대를 클릭한 경우 -> 이미 선택된 아군이 있으면 100% 즉시 공격 감행!
      if (unit.faction === "enemy") {
        if (selected && selected.faction === "ally" && !selected.acted) {
          executeDirectAttack(selected, unit);
          renderBattlefield();
          return;
        } else {
          // 선택된 아군이 아직 없으면 첫 번째 미행동 아군을 즉시 골라주고 그 적을 타격!
          const firstAlly = UNITS.find(u => u.faction === 'ally' && u.troops > 0 && !u.acted);
          if (firstAlly) {
            selectUnit(firstAlly);
            executeDirectAttack(firstAlly, unit);
            renderBattlefield();
            return;
          } else {
            selectUnit(unit);
            renderBattlefield();
            return;
          }
        }
      }
    }

    // 🎯 빈 타일 클릭 핸들러: 이동 & 실수 클릭 보호(Deselect Protection)
    function handleTileClick(q, r) {
      // 1. 공격/특기 조준 발동 모드 (화계 등 타일 조준)
      if (sam5BattleState.skillMode) {
        const target = sam5BattleState.attackableTargets.find(t => t.q === q && t.r === r);
        if (target) {
          executeSkillAction(sam5BattleState.skillMode, target);
        } else {
          logBattle("명령 대상이 올바르지 않아 군령을 철회했습니다.");
        }
        clearSkillMode();
        renderBattlefield();
        return;
      }

      const selectedUnit = sam5BattleState.selectedUnit;

      // 2. 이동 가능 타일 클릭 시 부대 이동
      const canMove = sam5BattleState.reachableHexes.find(h => h.q === q && h.r === r);
      if (canMove && selectedUnit && !selectedUnit.moved) {
        selectedUnit.q = q;
        selectedUnit.r = r;
        selectedUnit.moved = true;
        sam5BattleState.reachableHexes = [];

        // 보급창 도달 검사
        const destTerrain = (MAP_TERRAIN[r] && MAP_TERRAIN[r][q] !== undefined) ? MAP_TERRAIN[r][q] : 0;
        if (destTerrain === 4 && !sam5BattleState.supplyBurned) {
          triggerSupplyRaid(selectedUnit);
        } else if (destTerrain === 8 && !sam5BattleState.allySupplyBurned) {
          logBattle(`🌾 아군 ${selectedUnit.name} 부대가 본진 군량고를 경비하고 있습니다.`);
        } else {
          logBattle(`${selectedUnit.name} 부대가 진격했습니다. 이제 적을 클릭하여 공격하십시오!`);
        }

        playSound('fanfare');
        updateActionCommands();
        renderBattlefield();
        return;
      }

      // 3. 🛡️ 실수 클릭 보호: 빈 땅을 잘못 클릭해도 아군 부대 선택을 풀지 않음!
      if (selectedUnit && selectedUnit.faction === 'ally') {
        logBattle(`💡 이동할 수 없는 위치입니다. 녹색 이동 타일을 클릭하거나, 붉은 적군을 클릭하여 공격하십시오.`);
        return;
      }

      deselectUnit();
      renderBattlefield();
    }

    function handleHexClick(q, r) {
      const u = findUnitAt(q, r);
      if (u) {
        handleUnitClick(u);
      } else {
        handleTileClick(q, r);
      }
    }

    
    // ==========================================================================
    // 🛡️ 아군 부대 원클릭 선택 퀵바 실시간 렌더링 시스템
    // ==========================================================================
    function renderAllyQuickBar() {
      const container = document.getElementById("allyQuickSelectBar");
      if (!container) return;
      const allies = UNITS.filter(u => u.faction === 'ally' && u.troops > 0);
      const selected = sam5BattleState.selectedUnit;

      container.innerHTML = allies.map(u => {
        const isSel = selected && selected.id === u.id;
        const isActed = u.acted;
        
        let bgClass = "bg-slate-900 border-slate-700 text-slate-300 hover:bg-blue-900/60";
        if (isSel) {
          bgClass = "bg-amber-600 border-yellow-300 text-white font-black shadow-md ring-2 ring-yellow-400 animate-pulse";
        } else if (isActed) {
          bgClass = "bg-slate-950/70 border-slate-800 text-slate-500 opacity-60";
        }

        const actLabel = isActed ? '완료' : '대기';
        return `
          <button onclick="selectUnitById('${u.id}')" 
                  class="py-1 px-1.5 rounded border text-[11px] flex items-center justify-between transition ${bgClass}">
            <span class="flex items-center gap-1 font-bold">
              <span>${u.avatar}</span>
              <span class="truncate max-w-[65px]">${u.name}</span>
            </span>
            <span class="text-[9px] px-1 rounded ${isActed ? 'bg-slate-800 text-slate-400' : 'bg-cyan-900 text-cyan-200'}">
              ${actLabel}
            </span>
          </button>
        `;
      }).join('');
    }

    // ID로 부대 즉시 선택
    function selectUnitById(unitId) {
      if (sam5BattleState.battleOver || sam5BattleState.phase !== 'ally') return;
      const u = UNITS.find(unit => unit.id === unitId && unit.faction === 'ally' && unit.troops > 0);
      if (u) {
        selectUnit(u);
        playSound('fanfare');
        renderBattlefield();
      }
    }

    // ⚡ 원클릭 즉시 자동 공격: 현재 선택된 아군이 가장 가까운 적을 자동 타격!
    function onCmdAutoSmartAttack() {
      const u = sam5BattleState.selectedUnit;
      if (!u || u.acted || sam5BattleState.phase !== 'ally') {
        // 선택된 아군이 없으면 첫 번째 미행동 아군 자동 선택
        const firstAlly = UNITS.find(unit => unit.faction === 'ally' && unit.troops > 0 && !unit.acted);
        if (firstAlly) {
          selectUnit(firstAlly);
          onCmdAutoSmartAttack();
        } else {
          logBattle("행동 가능한 아군 부대가 없습니다. 턴을 종료하십시오.");
        }
        return;
      }

      // 살아있는 모든 적 중 가장 가까운 적 탐색
      const aliveEnemies = UNITS.filter(en => en.faction === 'enemy' && en.troops > 0);
      if (aliveEnemies.length === 0) {
        logBattle("전장에 생존한 적 부대가 없습니다!");
        return;
      }

      let closestEnemy = null;
      let minDistance = 999;
      aliveEnemies.forEach(en => {
        const d = getHexDistance(u.q, u.r, en.q, en.r);
        if (d < minDistance) {
          minDistance = d;
          closestEnemy = en;
        }
      });

      if (closestEnemy) {
        logBattle(`⚡ [자동 타격] ${u.name} 부대가 가장 인접한 적장 ${closestEnemy.name}을 정밀 조준하여 공격합니다!`);
        executeDirectAttack(u, closestEnemy);
        renderBattlefield();
      }
    }

    function selectUnit(unit) {
      if (!unit || unit.troops <= 0) return;
      sam5BattleState.selectedUnit = unit;
      updateUnitDetailCard(unit);

      if (unit.faction === "ally" && !unit.moved && !unit.acted && sam5BattleState.phase === "ally") {
        computeMovementRange(unit);
      } else {
        sam5BattleState.reachableHexes = [];
      }

      sam5BattleState.attackableTargets = [];
      updateActionCommands();
      renderAllyQuickBar();
    }

        function disableAllCommands() {
      const ids = ["btnAttack", "btnArchery", "btnFireSkill", "btnChaosSkill", "btnFlurry", "btnFormation", "btnDuel", "btnWait"];
      ids.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.disabled = true;
      });
    }

    function deselectUnit() {
      sam5BattleState.selectedUnit = null;
      sam5BattleState.reachableHexes = [];
      sam5BattleState.attackableTargets = [];
      clearSkillMode();
      document.getElementById("unitName").innerText = "부대를 선택하세요";
      document.getElementById("unitGeneralTitle").innerText = "-";
      document.getElementById("unitTroops").innerText = "-";
      document.getElementById("unitMorale").innerText = "-";
      document.getElementById("statWar").innerText = "-";
      document.getElementById("statInt").innerText = "-";
      document.getElementById("statLead").innerText = "-";
      document.getElementById("statChr").innerText = "-";
      document.getElementById("unitFormationBadge").classList.add("hidden");
      document.getElementById("unitSkillsList").innerHTML = `<span class="text-slate-500">부대를 클릭하십시오</span>`;
      disableAllCommands();
    }

    // ==========================================================================
    // 전략 기믹 1: 보급창고(군량고) 기습 점령 이벤트
    // ==========================================================================
        // ==========================================================================
    // 🌾 적 군량고 습격 및 아군 군량고 피습 처리
    // ==========================================================================
    function triggerSupplyRaid(hero) {
      if (sam5BattleState.supplyBurned) return;
      sam5BattleState.supplyBurned = true;
      logBattle(`🌾💥 [전략 대성공!] ${hero.name} 부대가 적의 군량고를 기습 점령 및 불태웠습니다! 적 전군 패닉 & 사기 급락!`);
      playSound('fire');

      // 적 전군 사기 급락 및 병력 25% 이탈
      UNITS.filter(u => u.faction === "enemy" && u.troops > 0).forEach(enemy => {
        enemy.morale = Math.max(15, enemy.morale - 45);
        const lost = Math.floor(enemy.troops * 0.25);
        enemy.troops -= lost;
        showDamagePop(enemy.q, enemy.r, `군량소실! -${lost}`);
      });

      const alertEl = document.getElementById("tacticalAlertText");
      if (alertEl) alertEl.innerText = "🎉 적 군량고 소실! 10턴 내에 전멸시킬 수 있는 절호의 기회입니다!";

      logMessage(`🔥 [적 군량고 점령 소각!] ${hero.name} 장군이 적 후방 보급창을 궤멸시켜 적 전군이 패닉에 빠졌습니다!`, 'text-yellow-300 font-extrabold text-sm');
      gainTroopExp(100, '적 군량고 소각 기습 대성공');
      alert(`🌾💥 [전략 대성공! 적 군량고 기습 소각!]

${hero.name} 부대가 적의 후방 군량고를 기습하여 잿더미로 만들었습니다!

▶ 적 전군 패닉: 사기 급락 (-45) & 병력 25% 즉시 탈영!
▶ 매 턴 적군 추가 탈영 발생! 승기를 잡았습니다!`);
    }

    function triggerAllySupplyRaid(enemyUnit) {
      if (sam5BattleState.allySupplyBurned) return;
      sam5BattleState.allySupplyBurned = true;
      logBattle(`🚨💥 [비보! 본진 군량고 피습!] 적장 ${enemyUnit.name} 부대가 아군의 본진 보급창(군량고)을 기습 점령 소각했습니다!`);
      playSound('fire');

      // 아군 전 부대 사기 급락 & 패닉
      UNITS.filter(u => u.faction === "ally" && u.troops > 0).forEach(ally => {
        ally.morale = Math.max(15, ally.morale - 40);
        showDamagePop(ally.q, ally.r, "🚨군량고 소각! 사기-40");
      });

      const alertEl = document.getElementById("tacticalAlertText");
      if (alertEl) alertEl.innerText = "🚨 아군 군량고 소실! 매 턴 보급 결핍 탈영 발생! 속전속결로 적을 섬멸하십시오!";

      logMessage(`🚨 [비상! 아군 군량고 소각!] 적 기습부대에게 본진 보급창을 빼앗겼습니다! 매 턴 군량 결핍 탈영 발생!`, 'text-red-400 font-extrabold text-sm');
      alert(`🚨 [비상! 아군 군량고 피습 소각!]

적 기습부대 ${enemyUnit.name}이 아군의 본진 보급창(군량고)을 점령하고 불태웠습니다!

▶ 아군 전군 패닉: 사기 급락 (-40)!
▶ 매 턴 보급 차단으로 병력 15% 탈영 손실 발생!
▶ 10턴 내로 적 본대를 섬멸하지 못하면 전군 와해됩니다!`);
    }

    // ==========================================================================
    // 이동 범위 연산 (추행진 기동력 +2 적용)
    // ==========================================================================
    // ==========================================================================
    // 🛡️ 헥스 인접 6방향 탐색 및 ZOC(통제선 / 적 돌파 저지) BFS 이동 알고리즘
    // ==========================================================================
    function getHexNeighbors(q, r) {
      const isOdd = (r % 2 !== 0);
      const diffs = isOdd ? [
        { dq: 1, dr: 0 }, { dq: -1, dr: 0 },
        { dq: 1, dr: -1 }, { dq: 0, dr: -1 },
        { dq: 1, dr: 1 }, { dq: 0, dr: 1 }
      ] : [
        { dq: 1, dr: 0 }, { dq: -1, dr: 0 },
        { dq: 0, dr: -1 }, { dq: -1, dr: -1 },
        { dq: 0, dr: 1 }, { dq: -1, dr: 1 }
      ];
      return diffs.map(d => ({ q: q + d.dq, r: r + d.dr }))
        .filter(n => n.q >= 0 && n.q < GRID_COLS && n.r >= 0 && n.r < GRID_ROWS);
    }

    function isEnemyAdjacent(q, r, friendlyFaction) {
      const neighbors = getHexNeighbors(q, r);
      return neighbors.some(n => {
        const u = findUnitAt(n.q, n.r);
        return u && u.troops > 0 && u.faction !== friendlyFaction;
      });
    }

    function computeMovementRange(unit) {
      sam5BattleState.reachableHexes = [];
      const form = FORMATIONS[unit.formation];
      // ⛩️ 대형 13x8 전장 맞춤 기동력 상향 (기본 4칸, 추행/기마 5~6칸)
      const baseMove = (unit.faction === 'ally' && gameState.troopLevel >= 3) ? 5 : 4;
      const maxMove = Math.max(3, baseMove + (form ? form.moveBonus : 0));

      // BFS 큐: { q, r, cost }
      const queue = [{ q: unit.q, r: unit.r, cost: 0 }];
      const visited = new Map();
      visited.set(`${unit.q},${unit.r}`, 0);

      while (queue.length > 0) {
        const curr = queue.shift();

        if (curr.cost >= maxMove) continue;

        const neighbors = getHexNeighbors(curr.q, curr.r);

        for (const n of neighbors) {
          const terrain = (MAP_TERRAIN[n.r] && MAP_TERRAIN[n.r][n.q] !== undefined) ? MAP_TERRAIN[n.r][n.q] : 0;

          // 🧱 성벽(3)은 아군/적군 모두 통과 불가!
          if (terrain === 3) continue;

          // ⛩️ 성문(9)은 아군이든 적군이든 누구나 자유롭게 드나들 수 있는 열린 관문!
          const isGateTile = (terrain === 9);

          // ⚠️ 다른 유닛이 있는 타일 판별
          const occupant = findUnitAt(n.q, n.r);
          
          // 적 유닛이 서 있는 타일은 뚫고 지나갈 수 없음 (적 돌파 저지)
          if (occupant && occupant.troops > 0 && occupant.faction !== unit.faction) {
            continue;
          }

          // 지형별 이동 비용: 성문(9)은 1, 평지/숲 1, 산악(2) 2, 독천(6) 2
          let moveCost = 1;
          if (terrain === 2 || terrain === 6) moveCost = 2;

          const nextCost = curr.cost + moveCost;
          if (nextCost > maxMove) continue;

          const key = `${n.q},${n.r}`;
          if (!visited.has(key) || visited.get(key) > nextCost) {
            visited.set(key, nextCost);

            // 다른 유닛이 없는 빈 타일(또는 자기 자신 타일)이면 이동 가능 타일로 등록
            if (!occupant || occupant.id === unit.id) {
              sam5BattleState.reachableHexes.push({ q: n.q, r: n.r });
            }

            // ⚠️ ZOC (Zone of Control) 규칙:
            // 적 부대와 바로 인접한 헥스에 진입하면 정지하지만,
            // ⛩️ 성문(9) 타일이거나 성문을 통과할 때는 관문 돌파 특권으로 ZOC 정지 없이 시원하게 통과 허용!
            const enteredZoc = isEnemyAdjacent(n.q, n.r, unit.faction);
            if (!enteredZoc || isGateTile) {
              queue.push({ q: n.q, r: n.r, cost: nextCost });
            }
          }
        }
      }
    }

    function updateUnitDetailCard(unit) {
      document.getElementById("unitName").innerText = unit.name;
      document.getElementById("unitGeneralTitle").innerText = `${unit.name} (${unit.title})`;
      document.getElementById("unitAvatar").innerText = unit.avatar;
      document.getElementById("unitTroops").innerText = unit.troops.toLocaleString();
      document.getElementById("unitMorale").innerText = unit.morale;

      document.getElementById("statWar").innerText = unit.war;
      document.getElementById("statInt").innerText = unit.int;
      document.getElementById("statLead").innerText = unit.lead;
      document.getElementById("statChr").innerText = unit.chr;

      const fBadge = document.getElementById("unitFormationBadge");
      const form = FORMATIONS[unit.formation];
      if (form) {
        fBadge.innerText = form.name;
        fBadge.style.backgroundColor = form.badgeBg;
        fBadge.style.color = form.color;
        fBadge.classList.remove("hidden");
      }

      const fTag = document.getElementById("unitFactionBadge");
      if (unit.faction === "ally") {
        fTag.innerText = "연합군";
        fTag.className = "text-[10px] px-1.5 py-0.5 rounded font-bold bg-blue-900 text-blue-200 border border-blue-500";
      } else {
        fTag.innerText = unit.isBoss ? "총대장(동탁군)" : "동탁군";
        fTag.className = "text-[10px] px-1.5 py-0.5 rounded font-bold bg-red-950 text-red-200 border border-red-500";
      }

      const sBox = document.getElementById("unitSkillsList");
      sBox.innerHTML = unit.skills.map(s => 
        `<span class="px-1.5 py-0.5 rounded bg-slate-800 text-amber-300 border border-amber-900/60 font-semibold">${s}</span>`
      ).join("");
    }

    // ==========================================================================
    // ⬛⬜ 바둑의 원리: 대상 유닛에 인접(거리 1)한 우군 부대 목록 반환
    // ==========================================================================
    function getSurroundingUnits(targetUnit, friendlyFaction) {
      if (!targetUnit) return [];
      return UNITS.filter(u => 
        u.faction === friendlyFaction &&
        u.troops > 0 &&
        getHexDistance(u.q, u.r, targetUnit.q, targetUnit.r) === 1
      );
    }

    // 황충 화살부대 특화 및 전술 군령 버튼 갱신
    // ==========================================================================
    // 🏹 명궁 판별 (황충 & 태사자): 진형 무관 초장거리 4칸 궁시 & 4칸 맹화시(불화살)
    // ==========================================================================
    function isMasterArcher(unit) {
      if (!unit) return false;
      const n = (unit.name || '') + ' ' + (unit.fullName || '');
      return n.includes('황충') || n.includes('태사자');
    }

    // ⬛⬜ 바둑의 원리: 대상 유닛에 인접(거리 1)한 우군 부대 목록 반환
    function getSurroundingUnits(targetUnit, friendlyFaction) {
      if (!targetUnit) return [];
      return UNITS.filter(u => 
        u.faction === friendlyFaction &&
        u.troops > 0 &&
        getHexDistance(u.q, u.r, targetUnit.q, targetUnit.r) === 1
      );
    }

    // 전술 군령 버튼 갱신
    function updateActionCommands() {
      const u = sam5BattleState.selectedUnit;
      if (!u || u.faction !== "ally" || u.acted || sam5BattleState.phase !== "ally") {
        disableAllCommands();
        return;
      }

      const isArcher = isMasterArcher(u);
      const adjEnemies = getEnemiesInRange(u, 1);
      const allEnemies = UNITS.filter(en => en.faction === "enemy" && en.troops > 0);

      const btnAtk = document.getElementById("btnAttack");
      const btnArc = document.getElementById("btnArchery");
      const btnFire = document.getElementById("btnFireSkill");
      const btnChaos = document.getElementById("btnChaosSkill");
      const btnFlurry = document.getElementById("btnFlurry");
      const btnForm = document.getElementById("btnFormation");
      const btnDuel = document.getElementById("btnDuel");
      const btnWait = document.getElementById("btnWait");

      // 1. 진형 변경 & 대기(행동완료)는 항시 활성화!
      if (btnForm) btnForm.disabled = false;
      if (btnWait) btnWait.disabled = false;

      // 2. 🗡️ 근접 공격: 적이 전장에 살아있으면 항시 활성화! (누르면 타겟 지정 후 돌격 공격!)
      if (btnAtk) {
        btnAtk.disabled = (allEnemies.length === 0);
        const canEncircle3 = adjEnemies.some(e => getSurroundingUnits(e, 'ally').length >= 3);
        if (canEncircle3) {
          btnAtk.innerHTML = '<span class="text-yellow-300 animate-pulse font-black">⚡ 3면포위 일제합공!</span>';
          btnAtk.className = "px-3 py-2 rounded bg-amber-600 hover:bg-amber-500 border-2 border-yellow-300 text-white font-black text-xs shadow-lg transition";
        } else if (adjEnemies.length > 0) {
          btnAtk.innerHTML = '🗡️ 근접 공격 (인접)';
          btnAtk.className = "px-3 py-2 rounded bg-blue-700 hover:bg-blue-600 border-2 border-cyan-400 text-white font-black text-xs shadow-lg transition animate-pulse";
        } else {
          btnAtk.innerHTML = '🗡️ 돌격 공격';
          btnAtk.className = "px-3 py-2 rounded bg-blue-900 hover:bg-blue-800 border border-blue-500 text-white font-bold text-xs shadow transition";
        }
      }

      // 3. 🏹 안행 궁시: 모든 장수 화살 사격 100% 항시 활성화! (사거리 4칸)
      if (btnArc) {
        btnArc.disabled = (allEnemies.length === 0);
        if (u.name.includes('황충')) {
          btnArc.innerHTML = '🏹 황충 신궁 (사거리4)';
          btnArc.className = "px-3 py-2 rounded bg-emerald-800 hover:bg-emerald-700 border-2 border-yellow-300 text-yellow-300 font-black text-xs shadow-lg transition";
        } else if (u.name.includes('태사자')) {
          btnArc.innerHTML = '🏹 태사자 맹궁 (사거리4)';
          btnArc.className = "px-3 py-2 rounded bg-cyan-800 hover:bg-cyan-700 border-2 border-cyan-300 text-cyan-200 font-black text-xs shadow-lg transition";
        } else if (u.name.includes('서황') || u.name.includes('공손찬')) {
          btnArc.innerHTML = `🏹 ${u.name} 명궁 (사거리4)`;
          btnArc.className = "px-3 py-2 rounded bg-teal-800 hover:bg-teal-700 border-2 border-yellow-400 text-yellow-200 font-black text-xs shadow-lg transition";
        } else {
          btnArc.innerHTML = '🏹 궁시 사격 (사거리4)';
          btnArc.className = "px-3 py-2 rounded bg-blue-900 hover:bg-blue-800 border-2 border-cyan-400 text-cyan-200 font-black text-xs shadow-lg transition";
        }
      }

      // 4. 🔥 불화살 & 화계
      if (btnFire) {
        btnFire.disabled = (allEnemies.length === 0);
        if (isArcher) {
          btnFire.innerHTML = `🔥 ${u.name} 맹화시 (불화살)`;
          btnFire.className = "px-3 py-2 rounded bg-red-800 hover:bg-red-700 border-2 border-yellow-400 text-yellow-300 font-black text-xs shadow-lg transition";
        } else {
          btnFire.innerHTML = '🔥 화계 (풍향확산)';
          btnFire.className = "px-3 py-2 rounded bg-slate-800 hover:bg-slate-700 border border-slate-600 text-slate-200 font-bold text-xs shadow transition";
        }
      }

      // 5. 🌀 혼란 & ⚡ 분기
      if (btnChaos) btnChaos.disabled = (allEnemies.length === 0);
      if (btnFlurry) btnFlurry.disabled = (allEnemies.length === 0);

      // 6. ⚔️ 일기토
      if (btnDuel) btnDuel.disabled = (allEnemies.length === 0);
    }

    // ==========================================================================
    // ⚔️ 전술 군령 실행 핸들러 모음 (안행 궁시 & 불화살 & 일제합공)
    // ==========================================================================
    function onCmdAttack() {
      const u = sam5BattleState.selectedUnit;
      if (!u || u.acted || sam5BattleState.phase !== 'ally') return;

      sam5BattleState.skillMode = 'attack';
      const adjEnemies = getEnemiesInRange(u, 1);
      
      if (adjEnemies.length > 0) {
        sam5BattleState.attackableTargets = adjEnemies;
        const encircled = adjEnemies.find(e => getSurroundingUnits(e, 'ally').length >= 3);
        if (encircled) {
          logBattle(`⬛⬜⚡ [바둑의 3면 포위망 감지!] ${encircled.name}을 클릭하여 일제합공(300% 극딜)을 감행하십시오!`);
        } else {
          logBattle(`🗡️ [돌격 공격] 공격할 인접 적 부대(붉은 타겟)를 클릭하십시오.`);
        }
      } else {
        // 인접한 적이 없으면 전장의 모든 적을 타겟으로 지정 (클릭 시 자동 돌격 진격 후 공격!)
        sam5BattleState.attackableTargets = UNITS.filter(en => en.faction === 'enemy' && en.troops > 0);
        logBattle(`🏇 [돌격 진격 공격] 타격할 적 부대(붉은 타겟)를 클릭하면 전속력으로 돌격하여 베어버립니다!`);
      }
      renderBattlefield();
    }

    function onCmdArchery() {
      const u = sam5BattleState.selectedUnit;
      if (!u || u.acted || sam5BattleState.phase !== 'ally') return;

      const isArcher = isMasterArcher(u);
      const arcRange = 4;
      sam5BattleState.skillMode = 'archery';
      
      const targets = getEnemiesInRange(u, arcRange);
      if (targets.length > 0) {
        sam5BattleState.attackableTargets = targets;
      } else {
        // 사거리 밖이면 전장의 모든 적을 타겟으로 지정하여 자동 돌격 후 사격!
        sam5BattleState.attackableTargets = UNITS.filter(en => en.faction === 'enemy' && en.troops > 0);
      }

      const title = isArcher ? (u.name.includes('황충') ? '황충 백발백중 신궁' : '태사자 강동맹궁') : '아군 원거리 궁시 사격';
      logBattle(`🏹 [${title}] 타격할 적 부대(붉은 타겟)를 클릭하여 화살비를 퍼부으십시오!`);
      renderBattlefield();
    }

    function onCmdFireSkill() {
      const u = sam5BattleState.selectedUnit;
      if (!u || u.acted || sam5BattleState.phase !== 'ally') return;

      const isArcher = isMasterArcher(u);
      const fireRange = isArcher ? 4 : 2; // 명궁(황충/태사자)은 사거리 4칸 원거리 불화살 폭격!

      sam5BattleState.skillMode = 'fire';
      sam5BattleState.attackableTargets = getEnemiesInRange(u, fireRange);

      if (isArcher) {
        const archerTitle = u.name.includes('황충') ? '황충 맹화시' : '태사자 불화살';
        logBattle(`🔥🏹 [${archerTitle}] 사거리 ${fireRange}칸 이내의 적을 클릭하여 불화살을 쏟아부으십시오! (화염 지속 생성)`);
      } else {
        logBattle(`🔥 [화계] 사거리 ${fireRange}칸 이내의 적이나 타일을 클릭하여 화공을 감행하십시오!`);
      }
      renderBattlefield();
    }

    function onCmdChaosSkill() {
      const u = sam5BattleState.selectedUnit;
      if (!u || u.acted || sam5BattleState.phase !== 'ally') return;

      sam5BattleState.skillMode = 'chaos';
      sam5BattleState.attackableTargets = getEnemiesInRange(u, 2);
      logBattle(`🌀 [혼란 계략] 혼란에 빠뜨릴 적 부대를 클릭하십시오. (사거리 2칸)`);
      renderBattlefield();
    }

    function onCmdFlurry() {
      const u = sam5BattleState.selectedUnit;
      if (!u || u.acted || sam5BattleState.phase !== 'ally') return;

      sam5BattleState.skillMode = 'attack';
      sam5BattleState.attackableTargets = getEnemiesInRange(u, 1);
      logBattle(`⚡ [분기 맹공] 인접한 적에게 강력한 연속 공격을 가합니다!`);
      renderBattlefield();
    }

    function clearSkillMode() {
      sam5BattleState.skillMode = null;
      sam5BattleState.attackableTargets = [];
    }

    function finishUnitAction(u) {
      u.acted = true;
      u.moved = true;
      sam5BattleState.selectedUnit = null;
      sam5BattleState.reachableHexes = [];
      sam5BattleState.attackableTargets = [];
      clearSkillMode();

      // 다음 행동 가능한 아군 자동 순차 선택 (원활한 조작 보장)
      const nextAlly = UNITS.find(unit => unit.faction === 'ally' && unit.troops > 0 && !unit.acted);
      if (nextAlly && sam5BattleState.phase === 'ally' && !sam5BattleState.battleOver) {
        sam5BattleState.selectedUnit = nextAlly;
        updateUnitDetailCard(nextAlly);
        if (!nextAlly.moved) computeMovementRange(nextAlly);
        logBattle(`🗡️ 다음 아군 [${nextAlly.name}] 부대로 순차 전환되었습니다. 적을 클릭하여 공격하십시오!`);
      } else {
        deselectUnit();
      }

      updateActionCommands();
      renderAllyQuickBar();
      renderBattlefield();

      // 아군 모든 부대가 행동 완료했는지 검사
      const activeAllies = UNITS.filter(unit => unit.faction === 'ally' && unit.troops > 0);
      const allActed = activeAllies.every(unit => unit.acted);
      if (allActed && !sam5BattleState.battleOver) {
        logBattle("🚩 아군 전 부대가 행동을 마쳤습니다. 턴을 종료하고 적군 턴으로 넘어갑니다.");
        setTimeout(() => {
          if (sam5BattleState.phase === 'ally') endPlayerTurn();
        }, 600);
      }
    }

    // ==========================================================================
    // 전투 액션 실행: 바둑 3면 포위 일제합공 & 황충/태사자 원거리 화살 및 불화살
    // ==========================================================================
    function executeSkillAction(mode, targetPos) {

      // ⚔️ [일기토 조준 돌격 처리]
      if (mode === 'duel' && targetUnit) {
        // 적장 인접 빈 타일로 질풍 이동
        const curDist = getHexDistance(u.q, u.r, targetUnit.q, targetUnit.r);
        if (curDist > 1 && !u.moved) {
          const adjHexes = getHexNeighbors(targetUnit.q, targetUnit.r);
          const emptyAdj = adjHexes.find(h => !findUnitAt(h.q, h.r) && MAP_TERRAIN[h.r] && MAP_TERRAIN[h.r][h.q] !== 3);
          if (emptyAdj) {
            u.q = emptyAdj.q;
            u.r = emptyAdj.r;
            u.moved = true;
          }
        }
        logBattle(`🏇⚔️ [질풍 쇄도 일기토!] ${u.name} 장군이 말을 몰아 적장 ${targetUnit.name}의 코앞으로 돌진하여 칼을 겨누었습니다!`);
        startTacticalDuel(u, targetUnit);
        return;
      }

      const u = sam5BattleState.selectedUnit;
      if (!u) return;
      const targetUnit = findUnitAt(targetPos.q, targetPos.r);
      if (!targetUnit) return;
      const isArcher = isMasterArcher(u);

      if (mode === 'attack' && targetUnit) {
        // [★돌격 이동 자동 결합★] 적과 거리가 1칸보다 멀고 아직 이동하지 않았다면 적 앞으로 즉시 쇄도 이동!
        const curDist = getHexDistance(u.q, u.r, targetUnit.q, targetUnit.r);
        if (curDist > 1 && !u.moved) {
          computeMovementRange(u);
          const adjHexes = getHexNeighbors(targetUnit.q, targetUnit.r);
          const chargeHex = sam5BattleState.reachableHexes.find(h => adjHexes.some(a => a.q === h.q && a.r === h.r));
          if (chargeHex) {
            u.q = chargeHex.q;
            u.r = chargeHex.r;
            u.moved = true;
            sam5BattleState.reachableHexes = [];
            logBattle(`🏇 [질풍 쇄도!] ${u.name} 부대가 적장 ${targetUnit.name}의 코앞으로 돌진하여 일격을 가합니다!`);
            playSound('fanfare');
          } else if (sam5BattleState.reachableHexes.length > 0) {
            // 가장 가까운 타일로 전진
            let bestHex = null;
            let bestD = 999;
            sam5BattleState.reachableHexes.forEach(h => {
              const d = getHexDistance(h.q, h.r, targetUnit.q, targetUnit.r);
              if (d < bestD) { bestD = d; bestHex = h; }
            });
            if (bestHex) {
              u.q = bestHex.q;
              u.r = bestHex.r;
              u.moved = true;
              sam5BattleState.reachableHexes = [];
            }
          }
        }
        // ⬛⬜ 바둑의 원리 및 포위망 검사
        const surroundingAllies = getSurroundingUnits(targetUnit, u.faction);
        const surroundCount = surroundingAllies.length;

        const adv = getElementAdvantage(u.element, targetUnit.element);
        let dmg = calculateCombatDamage(u, targetUnit, 'melee');

        if (surroundCount >= 3) {
          // ⬛⬜ 바둑의 원리: 3면 포위 일제합공 (활로 차단 극딜 300% & 적 반격 불가!)
          dmg = Math.floor(dmg * 2.8);
          logBattle(`⬛⬜⚡ [바둑의 3면 포위 일제합공 (圍棋 一齊攻擊)!]`);
          logBattle(`적장 ${targetUnit.name}의 3대 활로(숨구멍)를 완벽 차단! 포위한 [${surroundingAllies.map(a => a.name).join(', ')}] 부대가 일제히 쇄도하여 ${dmg.toLocaleString()} 섬멸 치명타를 가했습니다!`);
          playSound('fanfare');
          playSound('slash');
          showDamagePop(targetUnit.q, targetUnit.r, `⚡3면포위 일제공격! -${dmg}`);
          targetUnit.morale = Math.max(10, targetUnit.morale - 40);
          targetUnit.acted = true; // 혼란 행동불능

          applyDamage(targetUnit, dmg);
          surroundingAllies.forEach(a => gainTroopExp(60, '3면 포위 일제공격'));
          gainTroopExp(70, '바둑의 포위 섬멸 대승');
        } else if (surroundCount === 2) {
          // ⚔️ 2면 협공 (Pincer Attack: 대미지 +50% & 적 반격 절반)
          dmg = Math.floor(dmg * 1.5);
          logBattle(`⚔️🔥 [양면 협공!] 2개 부대가 적장 ${targetUnit.name}을 협공하여 ${dmg.toLocaleString()} 피해를 입혔습니다!`);
          playSound('slash');
          showDamagePop(targetUnit.q, targetUnit.r, `🔥협공! -${dmg}`);
          applyDamage(targetUnit, dmg);
          gainTroopExp(40, '양면 협공');

          if (targetUnit.troops > 0) {
            const counterDmg = Math.floor(calculateCombatDamage(targetUnit, u, 'melee') * 0.35);
            applyDamage(u, counterDmg);
          }
        } else {
          // 일반 1:1 돌격 교전
          logBattle(`🗡️ ${u.name} 부대가 ${targetUnit.name}에게 돌격을 감행합니다!`);
          playSound('slash');
          applyDamage(targetUnit, dmg);
          gainTroopExp(30, '돌격 교전');

          if (adv.isAdv) {
            logBattle(adv.text);
            playSound('fanfare');
          } else if (adv.isDisadv) {
            logBattle(adv.text);
          }

          if (targetUnit.troops > 0) {
            const counterDmg = Math.floor(calculateCombatDamage(targetUnit, u, 'melee') * 0.65);
            applyDamage(u, counterDmg);
          }
        }
      } else if (mode === 'archery' && targetUnit) {
        if (isArcher) {
          const archerTitle = u.name.includes('황충') ? '황충 백발백중 신궁' : '태사자 강동맹궁';
          logBattle(`🏹🎯 [${archerTitle} 원거리 저격!] 4칸 밖에서 뿜어진 화살이 ${targetUnit.name} 부대의 심장을 꿰뚫었습니다!`);
          playSound('arrow');
          const dmg = Math.floor(calculateCombatDamage(u, targetUnit, 'archery') * 1.5);
          applyDamage(targetUnit, dmg);
          showDamagePop(targetUnit.q, targetUnit.r, `🎯장거리 저격! -${dmg}`);
          gainTroopExp(45, '원거리 신궁 저격');
        } else {
          logBattle(`🏹 ${u.name} 부대의 화살비가 쏟아집니다! (사거리 4칸)`);
          playSound('arrow');
          const dmg = calculateCombatDamage(u, targetUnit, 'archery');
          applyDamage(targetUnit, dmg);
          gainTroopExp(30, '궁시 지원');
        }
      } else if (mode === 'fire') {
        if (isArcher && targetUnit) {
          // 황충 / 태사자 맹화시 (사거리 4칸 불화살 폭격)
          const archerTitle = u.name.includes('황충') ? '황충 맹화시' : '태사자 불화살';
          logBattle(`🔥🏹 [${archerTitle} 원거리 불화살 폭격!] 4칸 밖에서 날아든 불화살이 ${targetUnit.name} 부대 진영을 덮쳐 화염에 휩싸입니다!`);
          playSound('fire');
          const dmg = Math.floor(calculateCombatDamage(u, targetUnit, 'archery') * 1.7 + 900);
          applyDamage(targetUnit, dmg);
          sam5BattleState.fireTiles.push({ q: targetPos.q, r: targetPos.r, turns: 3 });
          targetUnit.morale = Math.max(10, targetUnit.morale - 35);
          showDamagePop(targetUnit.q, targetUnit.r, `🔥원거리 맹화시! -${dmg}`);
          gainTroopExp(50, '원거리 불화살 폭격 성공');
        } else {
          logBattle(`🔥 [대화계] 불길이 거세게 치솟습니다! 남동풍을 타고 번져갑니다.`);
          playSound('fire');
          sam5BattleState.fireTiles.push({ q: targetPos.q, r: targetPos.r, turns: 3 });
          gainTroopExp(50, '대화계 성공');
          if (targetUnit) {
            applyDamage(targetUnit, 1500);
            targetUnit.morale = Math.max(10, targetUnit.morale - 20);
          }
        }
      } else if (mode === 'chaos' && targetUnit) {
        const successRate = 55 + (u.int - targetUnit.int) * 2;
        if (Math.random() * 100 < successRate) {
          targetUnit.morale = Math.max(10, targetUnit.morale - 30);
          targetUnit.acted = true;
          gainTroopExp(50, '혼란 계략 성공');
          logBattle(`🌀 [혼란 대성공] ${targetUnit.name}의 군심이 무너져 행동 불능이 되었습니다!`);
          playSound('fanfare');
        } else {
          logBattle(`[혼란 실패] ${targetUnit.name}이 계략을 눈치챘습니다.`);
        }
      }

      finishUnitAction(u);
    }

    function calculateCombatDamage(attacker, defender, type) {
      const aForm = FORMATIONS[attacker.formation] || FORMATIONS.gyorin;
      const dForm = FORMATIONS[defender.formation] || FORMATIONS.gyorin;

      let atkPower = (attacker.war * 0.60 + attacker.lead * 0.40) * (attacker.troops / 4200);
      let defPower = (defender.lead * 0.60 + defender.war * 0.40) * (defender.troops / 4200);

      if (type === 'archery') {
        atkPower *= aForm.arcMod;
        if (defender.formation === 'bangwon') defPower *= 2.4;
      } else {
        atkPower *= aForm.atkMod;
        defPower *= dForm.defMod;
      }

      atkPower *= (attacker.morale / 100);

      // 🔥 난이도 황금 밸런스 계수 (초급: 1.2배 / 중급: 1.0배 실전 / 상급: 0.9배 긴장감)
      let diffMult = 1.0;
      if (attacker.faction === 'ally') {
        if (gameState.difficulty === 'easy') diffMult = 1.20;
        else if (gameState.difficulty === 'hard') diffMult = 0.90;
      } else {
        if (gameState.difficulty === 'easy') diffMult = 0.85;
        else if (gameState.difficulty === 'hard') diffMult = 1.25;
      }

      // 지형 방어 보너스 (숲: 1.15, 산악: 1.25, 관문: 1.80)
      const terrain = (defender.q >= 0 && defender.r >= 0 && MAP_TERRAIN[defender.r]) ? MAP_TERRAIN[defender.r][defender.q] : 0;
      if (terrain === 1) defPower *= 1.15;
      else if (terrain === 2) defPower *= 1.25;
      else if (terrain === 3) defPower *= 1.80;

      // 🔥 [쌍방 병종 숙련도 레벨 보정: 적군도 대등하게 강해짐!]
      const atkLvl = attacker.level || (attacker.faction === 'ally' ? (gameState.troopLevel || 1) : 1);
      atkPower *= (1.0 + (atkLvl - 1) * 0.055);

      // 방어력 레벨 보정: 고레벨 부대는 방어력도 탄탄해져 일격사 방지
      const defLvl = defender.level || (defender.faction === 'ally' ? (gameState.troopLevel || 1) : 1);
      defPower *= (1.0 + (defLvl - 1) * 0.05);

      // 🔮 5대 원소 부대 속성 상성 연산 (우세 시 대미지 1.5배, 열세 시 0.7배)
      const elemAdv = getElementAdvantage(attacker.element, defender.element);
      diffMult *= elemAdv.mult;

      let baseDamage = Math.floor(((atkPower / Math.max(10, defPower)) * 950 + Math.random() * 250) * diffMult);
      return Math.max(300, baseDamage);
    }

    function applyDamage(unit, damage) {
      unit.troops = Math.max(0, unit.troops - damage);
      showDamagePop(unit.q, unit.r, `-${damage}`);

      if (unit.troops <= 0) {
        logBattle(`☠️ [궤멸] 적장 ${unit.name} 부대가 전멸하여 패주했습니다!`);
        checkVictoryCondition();
      }
      renderBattlefield();
    }

    function showDamagePop(q, r, text) {
      const { x, y } = getHexPixel(q, r);
      const container = document.getElementById("damageOverlay");
      const pop = document.createElement("div");
      pop.className = "damage-pop text-red-500 font-black";
      pop.innerText = text;
      pop.style.left = `${x}px`;
      pop.style.top = `${y}px`;
      container.appendChild(pop);
      setTimeout(() => pop.remove(), 850);
    }

    function clearSkillMode() {
      sam5BattleState.skillMode = null;
      sam5BattleState.attackableTargets = [];
    }

    

    function onCmdWait() {
      if (sam5BattleState.selectedUnit) finishUnitAction(sam5BattleState.selectedUnit);
    }

    function finishUnitAction(unit) {
      unit.acted = true;
      unit.moved = true;
      clearSkillMode();
      deselectUnit();
      renderBattlefield();
      checkAllUnitsActed();
    }

    // ==========================================================================
    // 진형 변경 시스템
    // ==========================================================================
    function openFormationModal() {
      const u = sam5BattleState.selectedUnit;
      if (!u) return;
      const listEl = document.getElementById("formationChoiceList");
      listEl.innerHTML = "";

      u.availableFormations.forEach(fKey => {
        const form = FORMATIONS[fKey];
        const isCurrent = u.formation === fKey;
        const div = document.createElement("div");
        div.className = `p-2.5 rounded border cursor-pointer flex justify-between items-center transition ${isCurrent ? 'bg-amber-950 border-yellow-500' : 'bg-slate-900 border-slate-700 hover:border-yellow-600'}`;
        div.innerHTML = `
          <div>
            <div class="flex items-center gap-2">
              <span class="formation-badge" style="background:${form.badgeBg}; color:${form.color};">${form.name}</span>
              ${isCurrent ? '<span class="text-[10px] text-yellow-400 font-bold">(현재 진형)</span>' : ''}
            </div>
            <div class="text-[11px] text-slate-300 mt-1">${form.desc}</div>
          </div>
          <button class="sam5-btn px-2.5 py-1 text-xs rounded" ${isCurrent ? 'disabled' : ''}>
            ${isCurrent ? '유지' : '변환'}
          </button>
        `;
        div.onclick = () => {
          if (!isCurrent) {
            u.formation = fKey;
            logBattle(`🛡️ ${u.name}이 군세를 정비하여 [${form.name}]으로 진형을 바꾸었습니다!`);
            playSound('fanfare');
            closeFormationModal();
            updateUnitDetailCard(u);
            finishUnitAction(u);
          }
        };
        listEl.appendChild(div);
      });

      document.getElementById("formationModal").classList.remove("hidden");
    }

    function closeFormationModal() {
      document.getElementById("formationModal").classList.add("hidden");
    }


    // ==========================================================================
    // 🌐 천하 멀티플레이어 엔진 (PeerJS P2P 실시간 통신 & 로컬 핫시트)
    // ==========================================================================
    let peer = null;
    let peerConnections = []; // 호스트가 연결된 게스트들
    let hostConn = null; // 게스트가 연결된 호스트
    let isP2PHost = false;
    let myPeerId = null;
    let currentRoomId = null;

    let mpState = {
      isOnline: false,
      isHotseat: false,
      myPlayerId: null,
      myRuler: '유비',
      isReady: false,
      players: [], // { id, name, ruler, isHost, isReady }
      hotseatRulers: [],
      currentHotseatIdx: 0
    };

    function openMultiplayModal() {
      closeAllPopups();
      openModal('multiplay-modal');
      switchMultiplayTab('online');

      // URL에 ?room=SAM-XXXX 파라미터가 있으면 자동 방 참가창에 채워넣기
      const urlParams = new URLSearchParams(window.location.search);
      const roomParam = urlParams.get('room');
      if (roomParam) {
        document.getElementById('mp-join-room-id').value = roomParam.toUpperCase();
      }
    }

    function switchMultiplayTab(tab) {
      const tabOnline = document.getElementById('tab-mp-online');
      const tabHotseat = document.getElementById('tab-mp-hotseat');
      const contentOnline = document.getElementById('mp-online-content');
      const contentHotseat = document.getElementById('mp-hotseat-content');

      if (tab === 'online') {
        tabOnline.className = "px-4 py-2 font-black text-xs sm:text-sm rounded-t bg-indigo-900 text-yellow-300 border-t-2 border-l-2 border-r-2 border-indigo-400";
        tabHotseat.className = "px-4 py-2 font-bold text-xs sm:text-sm rounded-t bg-slate-800 text-slate-300 hover:text-white";
        contentOnline.classList.remove('hidden');
        contentHotseat.classList.add('hidden');
      } else {
        tabHotseat.className = "px-4 py-2 font-black text-xs sm:text-sm rounded-t bg-purple-900 text-yellow-300 border-t-2 border-l-2 border-r-2 border-purple-400";
        tabOnline.className = "px-4 py-2 font-bold text-xs sm:text-sm rounded-t bg-slate-800 text-slate-300 hover:text-white";
        contentHotseat.classList.remove('hidden');
        contentOnline.classList.add('hidden');
      }
    }

    // --------------------------------------------------------------------------
    // 🌐 [1. PeerJS 온라인 방 개설 (호스트)]
    // --------------------------------------------------------------------------
    function createP2PRoom() {
      if (typeof Peer === 'undefined') {
        alert("PeerJS 라이브러리를 불러오는 중입니다. 잠시 후 다시 시도해 주십시오.");
        return;
      }

      const randomCode = 'SAM3-' + Math.floor(1000 + Math.random() * 9000);
      currentRoomId = randomCode;
      isP2PHost = true;
      mpState.isOnline = true;
      mpState.myPlayerId = 'P1_HOST';
      mpState.myRuler = gameState.rulerName || '유비';
      mpState.isReady = true;

      mpState.players = [{
        id: mpState.myPlayerId,
        name: '방장 (' + (gameState.rulerName || '유비') + ')',
        ruler: mpState.myRuler,
        isHost: true,
        isReady: true
      }];

      peer = new Peer(currentRoomId);

      peer.on('open', (id) => {
        myPeerId = id;
        document.getElementById('mp-lobby-entry').classList.add('hidden');
        document.getElementById('mp-lobby-room').classList.remove('hidden');
        document.getElementById('mp-display-room-code').innerText = id;
        document.getElementById('mp-my-role-badge').innerText = "👑 방장";

        renderLobbyPlayers();
        logMessage(`🌐 [멀티 방 개설] 온라인 대기실 [${id}]이 개설되었습니다! 친구를 초대하십시오.`, 'text-indigo-300 font-black');
        playSfx('fanfare');
      });

      peer.on('connection', (conn) => {
        peerConnections.push(conn);

        conn.on('data', (data) => {
          handleHostReceivedData(conn, data);
        });

        conn.on('close', () => {
          peerConnections = peerConnections.filter(c => c !== conn);
          mpState.players = mpState.players.filter(p => p.conn !== conn);
          broadcastLobbyState();
          renderLobbyPlayers();
        });
      });

      peer.on('error', (err) => {
        console.error('Peer error:', err);
        alert('방 개설 중 오류가 발생했습니다: ' + err.type);
      });
    }

    // --------------------------------------------------------------------------
    // 🌐 [2. PeerJS 온라인 방 참가 (게스트)]
    // --------------------------------------------------------------------------
    function joinP2PRoom() {
      const inputEl = document.getElementById('mp-join-room-id');
      const targetRoom = (inputEl.value || '').trim().toUpperCase();
      if (!targetRoom) {
        alert("참가할 방 코드를 입력하십시오.");
        return;
      }

      if (typeof Peer === 'undefined') {
        alert("PeerJS 라이브러리를 불러오는 중입니다. 잠시 후 다시 시도해 주십시오.");
        return;
      }

      currentRoomId = targetRoom;
      isP2PHost = false;
      mpState.isOnline = true;
      mpState.myPlayerId = 'GUEST_' + Math.floor(Math.random() * 10000);
      mpState.myRuler = '조조'; // 게스트 기본 군주

      peer = new Peer();

      peer.on('open', (id) => {
        myPeerId = id;
        hostConn = peer.connect(targetRoom);

        hostConn.on('open', () => {
          document.getElementById('mp-lobby-entry').classList.add('hidden');
          document.getElementById('mp-lobby-room').classList.remove('hidden');
          document.getElementById('mp-display-room-code').innerText = targetRoom;
          document.getElementById('mp-my-role-badge').innerText = "⚔️ 참가자";
          document.getElementById('mp-my-role-badge').className = "text-[10px] px-1.5 py-0.5 rounded bg-amber-600 text-white font-bold";

          // 방장에게 참가 정보 전송
          hostConn.send({
            type: 'JOIN_LOBBY',
            playerId: mpState.myPlayerId,
            ruler: mpState.myRuler
          });

          playSfx('build');
        });

        hostConn.on('data', (data) => {
          handleGuestReceivedData(data);
        });

        hostConn.on('close', () => {
          alert('방장과의 연결이 끊어졌습니다.');
          leaveP2PRoom();
        });
      });

      peer.on('error', (err) => {
        alert('방에 접속할 수 없습니다. 방 코드를 확인해 주십시오: ' + targetRoom);
      });
    }

    // 호스트의 데이터 처리
    function handleHostReceivedData(conn, data) {
      if (data.type === 'JOIN_LOBBY') {
        const availableRulers = ['조조', '손책', '원소', '여포', '마등'];
        const taken = mpState.players.map(p => p.ruler);
        const assignedRuler = availableRulers.find(r => !taken.includes(r)) || '조조';

        const newPlayer = {
          id: data.playerId,
          name: `참가자 (${assignedRuler})`,
          ruler: assignedRuler,
          isHost: false,
          isReady: false,
          conn: conn
        };
        mpState.players.push(newPlayer);

        appendLobbyChat(`👑 [입장] 새로운 영걸 [${newPlayer.name}] 님이 방에 입장했습니다!`);
        broadcastLobbyState();
        renderLobbyPlayers();

      } else if (data.type === 'SET_READY') {
        const p = mpState.players.find(x => x.id === data.playerId);
        if (p) p.isReady = data.isReady;
        broadcastLobbyState();
        renderLobbyPlayers();

      } else if (data.type === 'CHAT_MSG') {
        appendLobbyChat(data.sender + ": " + data.msg);
        peerConnections.forEach(c => c.send(data));

      } else if (data.type === 'SYNC_TURN_ACTION') {
        // 인게임 턴 동기화 액션
        applyRemoteAction(data);
        peerConnections.forEach(c => {
          if (c !== conn) c.send(data);
        });
      }
    }

    // 게스트의 데이터 처리
    function handleGuestReceivedData(data) {
      if (data.type === 'LOBBY_STATE') {
        mpState.players = data.players;
        renderLobbyPlayers();

        // 내 군주 확인
        const me = mpState.players.find(p => p.id === mpState.myPlayerId);
        if (me) mpState.myRuler = me.ruler;

      } else if (data.type === 'CHAT_MSG') {
        appendLobbyChat(data.sender + ": " + data.msg);

      } else if (data.type === 'START_GAME') {
        // 호스트의 게임 시작 신호
        closeModal('multiplay-modal');
        logMessage(`🚀 [천하쟁패 개시!] 방장이 멀티플레이 대전을 시작했습니다!`, 'text-yellow-300 font-black text-sm');
        playSfx('fanfare');

        // 내 군주로 시점 전환
        if (mpState.myRuler) {
          const targetProv = PROVINCES.find(p => p.ruler === mpState.myRuler);
          if (targetProv) {
            gameState.rulerName = mpState.myRuler;
            gameState.myCapitalId = targetProv.id;
            gameState.selectedProvId = targetProv.id;
            renderMapPins();
            updateRightPanel(targetProv.id);
          }
        }

      } else if (data.type === 'SYNC_TURN_ACTION') {
        applyRemoteAction(data);
      }
    }

    function broadcastLobbyState() {
      const cleanPlayers = mpState.players.map(p => ({
        id: p.id,
        name: p.name,
        ruler: p.ruler,
        isHost: p.isHost,
        isReady: p.isReady
      }));

      peerConnections.forEach(c => {
        c.send({
          type: 'LOBBY_STATE',
          players: cleanPlayers
        });
      });
    }

    function renderLobbyPlayers() {
      const container = document.getElementById('mp-players-grid');
      if (!container) return;

      container.innerHTML = mpState.players.map(p => {
        const isMe = (p.id === mpState.myPlayerId);
        return `
          <div class="p-2.5 rounded border ${p.isReady ? 'bg-emerald-950/70 border-emerald-500' : 'bg-slate-800 border-slate-600'} flex items-center justify-between shadow">
            <div class="flex items-center gap-2">
              <span class="text-xl">${p.isHost ? '👑' : '⚔️'}</span>
              <div class="flex flex-col text-left">
                <span class="text-xs font-black text-white flex items-center gap-1">
                  ${p.name} ${isMe ? '<span class="text-[9px] px-1 bg-blue-600 text-white rounded">나</span>' : ''}
                </span>
                <span class="text-[10px] text-yellow-300 font-bold">담당 군주: [${p.ruler}]</span>
              </div>
            </div>
            <span class="text-[11px] font-black ${p.isReady ? 'text-emerald-300 animate-pulse' : 'text-slate-400'}">
              ${p.isReady ? '준비 완료!' : '대기 중...'}
            </span>
          </div>
        `;
      }).join('');

      // 호스트 전용: 모두 준비되면 게임 시작 버튼 노출
      const btnStart = document.getElementById('btn-mp-start');
      const allReady = mpState.players.every(p => p.isReady);
      if (isP2PHost && btnStart) {
        if (allReady && mpState.players.length >= 1) {
          btnStart.classList.remove('hidden');
        } else {
          btnStart.classList.add('hidden');
        }
      }
    }

    function togglePlayerReady() {
      mpState.isReady = !mpState.isReady;
      const btn = document.getElementById('btn-mp-ready');
      if (btn) {
        btn.innerText = mpState.isReady ? "✅ 준비 완료 (해제)" : "⭐ 준비 완료 (Ready)";
        btn.className = mpState.isReady ? "px-4 py-2 rounded bg-emerald-700 hover:bg-emerald-600 border border-emerald-300 text-white font-black text-xs shadow transition active:scale-95" : "px-4 py-2 rounded bg-amber-600 hover:bg-amber-500 border border-yellow-300 text-white font-black text-xs shadow transition active:scale-95";
      }

      if (isP2PHost) {
        const me = mpState.players.find(p => p.id === mpState.myPlayerId);
        if (me) me.isReady = mpState.isReady;
        broadcastLobbyState();
        renderLobbyPlayers();
      } else if (hostConn) {
        hostConn.send({
          type: 'SET_READY',
          playerId: mpState.myPlayerId,
          isReady: mpState.isReady
        });
      }
    }

    function copyInviteLink() {
      const inviteUrl = window.location.origin + window.location.pathname + '?room=' + currentRoomId;
      navigator.clipboard.writeText(inviteUrl).then(() => {
        alert(`🔗 [초대 링크 복사 완료!]

카톡이나 메신저로 친구에게 링크를 전달하십시오:
${inviteUrl}

친구가 링크를 클릭하면 즉시 이 방으로 접속됩니다!`);
      }).catch(() => {
        prompt("아래 링크를 복사하여 친구에게 전달하십시오:", inviteUrl);
      });
    }

    function sendLobbyChat() {
      const input = document.getElementById('mp-chat-input');
      const msg = (input.value || '').trim();
      if (!msg) return;
      input.value = '';

      const senderName = isP2PHost ? '방장' : '참가자';
      appendLobbyChat(`${senderName}: ${msg}`);

      const chatData = {
        type: 'CHAT_MSG',
        sender: senderName,
        msg: msg
      };

      if (isP2PHost) {
        peerConnections.forEach(c => c.send(chatData));
      } else if (hostConn) {
        hostConn.send(chatData);
      }
    }

    function appendLobbyChat(text) {
      const box = document.getElementById('mp-chat-logs');
      if (!box) return;
      const div = document.createElement('div');
      div.innerText = text;
      box.appendChild(div);
      box.scrollTop = box.scrollHeight;
    }

    function startMultiplayOnlineGame() {
      if (!isP2PHost) return;
      peerConnections.forEach(c => {
        c.send({ type: 'START_GAME' });
      });

      closeModal('multiplay-modal');
      logMessage(`🚀 [천하쟁패 개시!] 온라인 멀티플레이 실시간 대전을 시작합니다!`, 'text-yellow-300 font-black text-sm');
      playSfx('fanfare');
    }

    function leaveP2PRoom() {
      if (peer) peer.destroy();
      peer = null;
      peerConnections = [];
      hostConn = null;
      mpState.isOnline = false;
      document.getElementById('mp-lobby-entry').classList.remove('hidden');
      document.getElementById('mp-lobby-room').classList.add('hidden');
    }

    // --------------------------------------------------------------------------
    // 👥 [3. 한 기기 핫시트(Hotseat) 다인 대전 엔진]
    // --------------------------------------------------------------------------
    function startHotseatGame() {
      const selectedRulers = [];
      if (document.getElementById('hs-ruler-liubei').checked) selectedRulers.push('유비');
      if (document.getElementById('hs-ruler-caocao').checked) selectedRulers.push('조조');
      if (document.getElementById('hs-ruler-sunce').checked) selectedRulers.push('손책');
      if (document.getElementById('hs-ruler-yuanshao').checked) selectedRulers.push('원소');

      if (selectedRulers.length < 2) {
        alert("핫시트 다인 대전을 진행하려면 최소 2명 이상의 군주를 선택해야 합니다!");
        return;
      }

      mpState.isHotseat = true;
      mpState.hotseatRulers = selectedRulers;
      mpState.currentHotseatIdx = 0;

      closeModal('multiplay-modal');

      const firstRuler = selectedRulers[0];
      changeRulerTo(firstRuler);

      playSfx('fanfare');
      alert(`👥 [핫시트 다인 대전 개시!]

▶ 참가 군주: ${selectedRulers.join(', ')} (${selectedRulers.length}인 대전)

첫 번째 순서인 [${firstRuler}] 군주님의 턴입니다!

턴을 넘길 때마다 다음 플레이어에게 화면이 교대로 전환됩니다!`);
      logMessage(`👥 [핫시트 대전 개시] ${selectedRulers.join(', ')} 군주 간의 천하쟁패가 시작되었습니다!`, 'text-purple-300 font-black text-sm');
    }

    function nextHotseatTurn() {
      if (!mpState.isHotseat || mpState.hotseatRulers.length === 0) return;

      mpState.currentHotseatIdx = (mpState.currentHotseatIdx + 1) % mpState.hotseatRulers.length;
      const nextRuler = mpState.hotseatRulers[mpState.currentHotseatIdx];

      changeRulerTo(nextRuler);
      playSfx('fanfare');

      alert(`👥 [차례 교대 - ${nextRuler} 군주님의 턴!]

화면을 [${nextRuler}] 플레이어에게 넘겨주십시오!

전략 행동력이 충전되었으며, 명령을 수행하십시오!`);
      logMessage(`👑 [차례 교대] 이제부터 [${nextRuler}] 군주님의 지휘 차례입니다!`, 'text-yellow-300 font-black');
    }

    function changeRulerTo(rulerName) {
      const prov = PROVINCES.find(p => p.ruler === rulerName);
      if (!prov) return;

      gameState.rulerName = rulerName;
      gameState.myCapitalId = prov.id;
      gameState.selectedProvId = prov.id;
      gameState.actionPoints = getMaxActionPoints();

      renderMapPins();
      updateRightPanel(prov.id);
      updateActionPointUI();
    }

    // 턴 넘김 시 핫시트 차례 교대 연결
    const origExecuteRest = executeRest;
    executeRest = function() {
      origExecuteRest();
      if (mpState.isHotseat) {
        setTimeout(() => {
          nextHotseatTurn();
        }, 300);
      }
    };


    // ==========================================================================
    // 전략 기믹 2: 일기토(一騎討) 일격필살 시스템
    // ==========================================================================
    

    // [구버전 progressDuelRound 및 alert창 완전 삭제됨]
    function closeDuelModal() {
      document.getElementById("duelModal").classList.add("hidden");
      if (sam5BattleState.selectedUnit) finishUnitAction(sam5BattleState.selectedUnit);
    }

    // ==========================================================================
    // 10턴 턴 진행 및 화계 풍향 확산 시스템
    // ==========================================================================
    function checkAllUnitsActed() {
      const allDone = UNITS.filter(u => u.faction === "ally" && u.troops > 0).every(u => u.acted);
      if (allDone && sam5BattleState.phase === 'ally' && !sam5BattleState.battleOver) {
        logBattle("🚩 아군 전 부대 행동 완료! 자동으로 적군 반격 턴으로 전환됩니다.");
        setTimeout(() => {
          endPlayerTurn();
        }, 800);
      }
    }

    function endPlayerTurn() {
      if (sam5BattleState.phase !== "ally" || sam5BattleState.battleOver) return;
      sam5BattleState.phase = "enemy";
      document.getElementById("btnEndTurn").disabled = true;
      document.getElementById("turnInfo").innerText = `제 ${sam5BattleState.turn} / 10 턴 [적군 반격 개시]`;
      logBattle("🚩 동탁군이 북을 울리며 전면 반격을 개시합니다!");
      playSound('drum');

      setTimeout(() => {
        runEnemyAI();
      }, 700);
    }

    
    // ==========================================================================
    // ⚔️ [전장 1:1 일기토] 거리 제한 박멸 & 전장의 모든 적장 돌격 결투 시스템
    // ==========================================================================
    function onCmdDuel() {
      let u = sam5BattleState.selectedUnit;
      if (!u || u.acted || sam5BattleState.phase !== 'ally') {
        // 선택된 아군이 없으면 최강 무력 장수(관우/장비/조운 등) 자동 선택
        const readyAlly = UNITS.find(unit => unit.faction === 'ally' && unit.troops > 0 && !unit.acted);
        if (readyAlly) {
          selectUnit(readyAlly);
          u = readyAlly;
        } else {
          logBattle("행동 가능한 아군 장수가 없습니다.");
          return;
        }
      }

      // 생존한 모든 적 부대 탐색
      const aliveEnemies = UNITS.filter(e => e.faction === 'enemy' && e.troops > 0);
      if (aliveEnemies.length === 0) {
        logBattle("전장에 생존한 적장이 없습니다!");
        return;
      }

      // 인접한 적이 있으면 최우선 적장과 즉시 일기토!
      const adjEnemies = getEnemiesInRange(u, 1);
      if (adjEnemies.length > 0) {
        const target = adjEnemies.find(e => e.isBoss) || adjEnemies[0];
        logBattle(`⚔️🏇 [일기토 신청!] ${u.name} 장군이 인접한 적장 [${target.name}]에게 1:1 결투를 신청했습니다!`);
        startTacticalDuel(u, target);
        return;
      }

      // 인접한 적이 없더라도 전장에서 가장 위협적인 적장(보스 우선, 또는 최단거리 적장)에게 즉시 질풍 돌격 결투 개시!
      const target = aliveEnemies.find(e => e.isBoss) || aliveEnemies[0];
      logBattle(`⚔️🏇 [질풍 돌격 일기토!] ${u.name} 장군이 말을 몰아 적장 [${target.name}] 앞으로 번개같이 돌격하여 즉시 1:1 진검승부를 개시합니다!`);
      playSound('fanfare');
      startTacticalDuel(u, target);
    }

    // 전술 헥스 전장 일기토 개시 함수
    function startTacticalDuel(allyUnit, enemyUnit) {
      sam5DuelState.p1 = allyUnit;
      sam5DuelState.p2 = enemyUnit;
      sam5DuelState.p1Hp = Math.max(30, 100 - (allyUnit.fatigue || 0));
      sam5DuelState.p2Hp = Math.max(30, 100 - (enemyUnit.fatigue || 10));
      sam5DuelState.round = 1;
      sam5DuelState.battleOver = false;
      sam5DuelState.isInvasionDuel = false; // 전장 헥스 일기토

      // 6대 전술 버튼 활성화 & 결과 바 숨김
      const actionGrid = document.getElementById("duelActionGrid");
      const resultBar = document.getElementById("duelResultBar");
      if (actionGrid) actionGrid.classList.remove("hidden");
      if (resultBar) resultBar.classList.add("hidden");

      const roundBadge = document.getElementById("duelRoundBadge");
      if (roundBadge) roundBadge.innerText = "제 1 합";

      const p1HpTxt = document.getElementById("duelP1HpText");
      const p2HpTxt = document.getElementById("duelP2HpText");
      if (p1HpTxt) p1HpTxt.innerText = `${sam5DuelState.p1Hp} / 100 HP`;
      if (p2HpTxt) p2HpTxt.innerText = `${sam5DuelState.p2Hp} / 100 HP`;

      const bannerImg = document.getElementById("duelBannerImg");
      if (bannerImg && typeof GLOBAL_SAM3_ASSETS !== 'undefined') {
        bannerImg.src = GLOBAL_SAM3_ASSETS.duelReady;
      }

      const p1NameEl = document.getElementById("duelP1Name");
      if (p1NameEl) p1NameEl.innerText = allyUnit.name;
      const p1WarEl = document.getElementById("duelP1War");
      if (p1WarEl) p1WarEl.innerText = "무력 " + (allyUnit.war || 95);
      const p1AvatarEl = document.getElementById("duelP1Avatar");
      if (p1AvatarEl) p1AvatarEl.innerText = allyUnit.icon || '🐉';
      const p1HpEl = document.getElementById("duelP1Hp");
      if (p1HpEl) p1HpEl.style.width = sam5DuelState.p1Hp + "%";

      const p2NameEl = document.getElementById("duelP2Name");
      if (p2NameEl) p2NameEl.innerText = enemyUnit.name;
      const p2WarEl = document.getElementById("duelP2War");
      if (p2WarEl) p2WarEl.innerText = "무력 " + (enemyUnit.war || 90);
      const p2AvatarEl = document.getElementById("duelP2Avatar");
      if (p2AvatarEl) p2AvatarEl.innerText = enemyUnit.avatar || '👹';
      const p2HpEl = document.getElementById("duelP2Hp");
      if (p2HpEl) p2HpEl.style.width = sam5DuelState.p2Hp + "%";

      const narrativeEl = document.getElementById("duelNarrative");
      if (narrativeEl) {
        narrativeEl.innerHTML = `<p class="text-yellow-300 font-black">⚔️ [일기토 개시!] ${allyUnit.name} vs ${enemyUnit.name}! 적장의 목을 베면 적 부대가 즉시 전멸합니다!</p>`;
      }

      const btnRound = document.getElementById("btnDuelRound");
      if (btnRound) btnRound.classList.remove("hidden");
      const btnClose = document.getElementById("btnDuelClose");
      if (btnClose) btnClose.classList.add("hidden");

      playSound('fanfare');
      openModal("duelModal");
    }

    // ==========================================================================
    // 🤖 [적군 AI 전면 혁신] 성벽 우회 진격 & 궁시 사격 & 돌격 공격 스마트 AI
    // ==========================================================================
    // ==========================================================================
    // 🧭 헥스 전장 스마트 BFS 최단 경로 탐색기 (성문 통과 & 장애물 우회)
    // ==========================================================================
    function getNextStepTowards(startQ, startR, targetQ, targetR) {
      if (getHexDistance(startQ, startR, targetQ, targetR) <= 1) {
        return null; // 이미 인접함
      }

      const queue = [{ q: startQ, r: startR, firstStep: null }];
      const visited = new Set();
      visited.add(`${startQ},${startR}`);

      let closestFallback = null;
      let minFallbackDist = getHexDistance(startQ, startR, targetQ, targetR);

      while (queue.length > 0) {
        const curr = queue.shift();
        const distToTarget = getHexDistance(curr.q, curr.r, targetQ, targetR);

        if (distToTarget <= 1) {
          return curr.firstStep; // 타겟 인접 최단경로의 첫 발자국 반환!
        }

        const neighbors = getHexNeighbors(curr.q, curr.r);
        for (const n of neighbors) {
          if (n.q < 0 || n.q >= GRID_COLS || n.r < 0 || n.r >= GRID_ROWS) continue;
          const key = `${n.q},${n.r}`;
          if (visited.has(key)) continue;

          const terrain = (MAP_TERRAIN[n.r] && MAP_TERRAIN[n.r][n.q] !== undefined) ? MAP_TERRAIN[n.r][n.q] : 0;
          if (terrain === 3) continue; // 성벽(3) 통과 불가 (성문은 통과 가능)

          const occupied = findUnitAt(n.q, n.r);
          if (occupied && !(n.q === targetQ && n.r === targetR)) continue; // 다른 유닛 통과 불가

          visited.add(key);
          const firstStep = curr.firstStep || { q: n.q, r: n.r };
          queue.push({ q: n.q, r: n.r, firstStep: firstStep });

          const d = getHexDistance(n.q, n.r, targetQ, targetR);
          if (d < minFallbackDist) {
            minFallbackDist = d;
            closestFallback = firstStep;
          }
        }
      }

      return closestFallback;
    }

    // ==========================================================================
    // 🤖 [적군 AI 전면 대개혁] 모든 적군이 성문을 통과하여 맹렬히 진격 & 공격!
    // ==========================================================================
    function runEnemyAI() {
      const enemies = UNITS.filter(u => u.faction === "enemy" && u.troops > 0);
      let step = 0;

      function executeNextEnemy() {
        if (step >= enemies.length || sam5BattleState.battleOver) {
          finishFullTurn();
          return;
        }

        const enemy = enemies[step];
        if (!enemy || enemy.troops <= 0) {
          step++;
          setTimeout(executeNextEnemy, 200);
          return;
        }

        const allies = UNITS.filter(u => u.faction === "ally" && u.troops > 0);
        if (allies.length === 0) {
          finishFullTurn();
          return;
        }

        // 가장 가까운 아군 또는 유비 탐색
        let targetAlly = allies[0];
        let minDist = 999;
        allies.forEach(a => {
          let d = getHexDistance(enemy.q, enemy.r, a.q, a.r);
          if (a.name.includes('유비')) d -= 1.2;
          if (d < minDist) {
            minDist = d;
            targetAlly = a;
          }
        });

        const isArcher = (enemy.name.includes('태사자') || enemy.formation === 'anhaeng' || enemy.role === 'archer');
        const attackRange = isArcher ? 3 : 1;
        let curDist = getHexDistance(enemy.q, enemy.r, targetAlly.q, targetAlly.r);

        // 1. 이미 사거리 내에 있는 경우 -> 즉각 공격!
        if (curDist <= attackRange) {
          performEnemyAttack(enemy, targetAlly, isArcher && curDist > 1);
        } else {
          // 2. 사거리 밖인 경우 -> BFS 길찾기로 1~2칸 성문 통과 진격!
          for (let moveCount = 0; moveCount < 2; moveCount++) {
            const nextStep = getNextStepTowards(enemy.q, enemy.r, targetAlly.q, targetAlly.r);
            if (nextStep && !findUnitAt(nextStep.q, nextStep.r)) {
              enemy.q = nextStep.q;
              enemy.r = nextStep.r;
            } else {
              break;
            }
          }

          logBattle(`🏇 적장 [${enemy.name}] 부대가 성문을 뚫고 아군 [${targetAlly.name}]을 향해 전속력 진격합니다!`);

          // 이동 후 사거리 검사 및 공격
          curDist = getHexDistance(enemy.q, enemy.r, targetAlly.q, targetAlly.r);
          if (curDist <= attackRange) {
            performEnemyAttack(enemy, targetAlly, isArcher && curDist > 1);
          }
        }

        enemy.acted = true;
        renderBattlefield();
        step++;
        setTimeout(executeNextEnemy, 450);
      }

      function performEnemyAttack(attacker, target, isRanged) {
        if (isRanged) {
          logBattle(`🏹🔥 [적군 궁시 사격!] 적장 ${attacker.name}이 아군 ${target.name}에게 빗발치는 화살비를 퍼부었습니다!`);
          playSound('arrow');
        } else {
          logBattle(`🗡️💥 [적군 맹공 돌격!] 적장 ${attacker.name}이 아군 ${target.name}에게 돌격을 감행했습니다!`);
          playSound('slash');
        }
        const dmg = calculateCombatDamage(attacker, target, isRanged ? 'archery' : 'melee');
        applyDamage(target, dmg);
        showDamagePop(target.q, target.r, `💥 -${dmg}`);
      }

      executeNextEnemy();
    }

    function finishFullTurn() {
      sam5BattleState.turn++;

      // 10턴 초과 시 타임오버 패배 판정!
      if (sam5BattleState.turn > MAX_TURNS) {
        checkTimeoutBattleResult();
        return;
      }

      sam5BattleState.phase = "ally";
      document.getElementById("btnEndTurn").disabled = false;
      document.getElementById("turnInfo").innerText = `제 ${sam5BattleState.turn} / 10 턴 [연합군 행동]`;

      // 10턴 게이지 업데이트
      const turnsLeft = MAX_TURNS - sam5BattleState.turn + 1;
      document.getElementById("turnCountdownText").innerText = `${turnsLeft} 턴 남음!`;
      const percent = (turnsLeft / MAX_TURNS) * 100;
      const barEl = document.getElementById("turnProgressBar");
      barEl.style.width = `${percent}%`;

      if (turnsLeft <= 3) {
        barEl.className = "turn-meter-bar h-full rounded-full bg-red-600 animate-pulse";
        document.getElementById("turnCountdownText").className = "text-red-500 font-black animate-ping";
      }

      // 전략 기믹 3: 남동풍을 타고 화계(불길) 확산
      const newFires = [];
      sam5BattleState.fireTiles.forEach(f => {
        f.turns--;
        if (f.turns > 0) {
          newFires.push(f);
          // 40% 확률로 남동쪽 (q+1, r) 또는 (q, r+1)로 불길 확산
          if (Math.random() < 0.45 && f.q + 1 < GRID_COLS) {
            newFires.push({ q: f.q + 1, r: f.r, turns: 2 });
          }
        }
      });
      sam5BattleState.fireTiles = newFires;

      // 불타는 타일 위의 부대에게 화염 피해
      sam5BattleState.fireTiles.forEach(f => {
        const u = findUnitAt(f.q, f.r);
        if (u) {
          applyDamage(u, 750);
          logBattle(`🔥 ${u.name} 부대가 불길에 휩싸여 큰 피해를 입었습니다!`);
        }
      });

      // 부대 턴 리셋
      UNITS.forEach(u => {
        u.moved = false;
        u.acted = false;
      });

      logBattle(`제 ${sam5BattleState.turn} 턴 시작! 남은 기회는 ${turnsLeft}번입니다.`);
      deselectUnit();
      renderBattlefield();
    }

    // ==========================================================================
    // 승패 판정 시스템 (10턴 룰)
    // ==========================================================================
    function checkVictoryCondition() {
      const enemiesAlive = UNITS.some(u => u.faction === "enemy" && u.troops > 0);
      const alliesAlive = UNITS.some(u => u.faction === "ally" && u.troops > 0);
      const boss = UNITS.find(u => u.isBoss);

      const targetRuler = (hexBattleContext.targetProv && hexBattleContext.targetProv.ruler) ? hexBattleContext.targetProv.ruler : '적';
      if (boss && boss.troops <= 0) {
        triggerVictory(`${targetRuler}군의 총대장 ${boss.name}이(가) 퇴각했습니다! 적 군세가 붕괴하여 대승을 거두었습니다!`);
      } else if (!enemiesAlive) {
        triggerVictory(`${targetRuler}군 전 부대를 궤멸시켰습니다! 천하에 이름을 떨친 완벽한 승리입니다!`);
      } else if (!alliesAlive) {
        triggerDefeat("아군 전 부대가 전멸하여 패배했습니다...");
      }
    }

    
    let currentInvasionContext = null;

    function triggerEnemyInvasion(enemyProv) {
      if (sam5BattleState.battleOver === false && sam5BattleState.turn > 1) return;
      const myCapital = getMyCapital();
      if (!myCapital) return;

      currentInvasionContext = {
        enemyProv: enemyProv,
        targetProv: myCapital,
        enemyLeader: enemyProv.leader || enemyProv.ruler,
        soldiers: enemyProv.soldiers || 25000
      };

      const desc = document.getElementById("enemyInvasionDesc");
      if (desc) {
        desc.innerHTML = `
          <div class="font-black text-red-300 text-base mb-1">
            🚨 ${enemyProv.ruler}군의 맹장 [${currentInvasionContext.enemyLeader}] 장군이 병력 ${currentInvasionContext.soldiers.toLocaleString()}명을 이끌고 아군 영지 [${myCapital.name}]으로 침공해 왔습니다!
          </div>
          <div class="text-xs text-slate-300">
            영지가 함락될 위기입니다! 1:1 일기토를 신청하여 적장을 일격에 생포하거나, 전군을 집결시켜 10턴 헥스 영지 방어전에 돌입하십시오!
          </div>
        `;
      }
      openModal('enemy-invasion-modal');
      playSfx('warning');
      logMessage("🚨 [적군 침공 경보!] " + enemyProv.ruler + "군이 아군 본거지 " + myCapital.name + "으로 침공했습니다!", 'text-red-400 font-black');
    }

    function resolveInvasionByDuel() {
      closeModal('enemy-invasion-modal');
      if (!currentInvasionContext) return;

      const allyDuelist = MY_OFFICERS.find(o => o.id === 'guan_yu') || MY_OFFICERS[0];
      const enemyDuelist = {
        name: currentInvasionContext.enemyLeader,
        war: 92,
        avatar: '👹',
        title: '적 침공 총대장',
        fatigue: 15
      };

      sam5DuelState.p1 = allyDuelist;
      sam5DuelState.p2 = enemyDuelist;
      sam5DuelState.p1Hp = Math.max(25, 100 - (allyDuelist.fatigue || 0));
      sam5DuelState.p2Hp = Math.max(25, 100 - enemyDuelist.fatigue);
      sam5DuelState.round = 1;
      sam5DuelState.isInvasionDuel = true;

      document.getElementById("duelP1Name").innerText = allyDuelist.name + " (피로 " + (allyDuelist.fatigue || 0) + "%)";
      document.getElementById("duelP1War").innerText = "무력 " + allyDuelist.war;
      document.getElementById("duelP1Avatar").innerText = allyDuelist.icon || '🐉';
      document.getElementById("duelP1Hp").style.width = sam5DuelState.p1Hp + "%";

      document.getElementById("duelP2Name").innerText = enemyDuelist.name + " (피로 " + enemyDuelist.fatigue + "%)";
      document.getElementById("duelP2War").innerText = "무력 " + enemyDuelist.war;
      document.getElementById("duelP2Avatar").innerText = enemyDuelist.avatar;
      document.getElementById("duelP2Hp").style.width = sam5DuelState.p2Hp + "%";

      document.getElementById("duelNarrative").innerHTML = `<p class="text-yellow-300 font-black">🚨 [영지의 운명이 걸린 일기토!] 승리 시 적장 생포! 패배 시 즉시 처형되어 게임오버!</p>`;
      document.getElementById("btnDuelRound").classList.remove("hidden");
      document.getElementById("btnDuelClose").classList.add("hidden");

      openModal("duelModal");
    }

    function resolveInvasionByHexBattle() {
      closeModal('enemy-invasion-modal');
      if (!currentInvasionContext) return;
      openHexBattle(currentInvasionContext.enemyProv, currentInvasionContext.targetProv);
    }

    function triggerGameOver(reasonText) {
      closeAllPopups();
      sam5BattleState.battleOver = true;
      playSound('fire');

      const reasonBox = document.getElementById("gameOverReason");
      if (reasonBox) {
        reasonBox.innerHTML = `
          <div class="text-red-400 font-black text-base mb-1">
            💥 통한의 패전 - ${reasonText}
          </div>
          <div class="text-xs text-slate-300 leading-relaxed">
            군주 ${gameState.rulerName}의 군세가 전멸하여 본거지가 함락되었고, 붙잡힌 군주는 적군 총사령관에 의해 형장의 이슬로 사라졌습니다.<br><br>
            이로써 난세를 평정하고 한실을 부흥시키려던 삼국 통일의 대업은 영원히 역사 속으로 사라졌습니다...
          </div>
        `;
      }
      openModal('game-over-modal');
      logMessage("💀 [게임오버] " + reasonText + " 천하통일의 대업이 종결되었습니다.", 'text-red-500 font-black');
    }

    function triggerVictory(msg) {
      openModal('battle-victory-modal');
      gainTroopExp(150, '10턴 결전 대승리');
      if (sam5BattleState.battleOver) return;
      sam5BattleState.battleOver = true;
      playSound('fanfare');
      
      const targetName = (hexBattleContext.targetProv && hexBattleContext.targetProv.name) ? hexBattleContext.targetProv.name : '적 영지';
      logBattle(`🏆 대승리! ${msg}`);
      logMessage(`🎉🏆 [전쟁 대승리!] ${targetName}을(를) 격파하고 완전히 점령했습니다! 전국 지도로 개선 복귀합니다.`, 'text-yellow-300 font-black text-sm');

      alert(`🎉🏆 [대승리 - 10턴 결전 승리!]\n\n${msg}\n소요 턴: ${sam5BattleState.turn}턴만에 완벽한 승리를 거두었습니다!\n\n▶ [확인]을 누르면 전국 지도로 복귀하여 영지를 점령하고 포로를 처분합니다.`);
      
      // 즉시 전국 지도로 복귀하며 영지 점령 및 포로 처분 모달 호출!
      closeHexBattle(true);
    }

        // 10턴 경과 시 승패 및 무승부(비김) 정밀 판정
    function checkTimeoutBattleResult() {
      const aliveAllies = UNITS.filter(u => u.faction === 'ally' && u.troops > 0);
      const aliveEnemies = UNITS.filter(u => u.faction === 'enemy' && u.troops > 0);

      const allyTotal = aliveAllies.reduce((sum, u) => sum + u.troops, 0);
      const enemyTotal = aliveEnemies.reduce((sum, u) => sum + u.troops, 0);

      if (allyTotal > enemyTotal * 1.3) {
        triggerVictory();
      } else if (Math.abs(allyTotal - enemyTotal) <= enemyTotal * 0.4 || (aliveAllies.length > 0 && aliveEnemies.length > 0)) {
        // 🤝 1번 비김 (명예로운 무승부!)
        triggerDraw("10턴 간의 혈전 끝에 양군 모두 군량이 소진되어 명예로운 무승부로 전선을 물렸습니다!");
      } else {
        triggerDefeat("10턴이 경과하여 적 증원군 10만 대군이 당도했습니다! 연합군은 전선을 보존하며 철수했습니다.");
      }
    }

    function triggerDraw(reason) {
      if (sam5BattleState.battleOver) return;
      sam5BattleState.battleOver = true;
      playSound('drum');
      logBattle(`🤝 [무승부 (비김)] ${reason}`);
      logMessage(`🤝 [전투 무승부] 10턴 간의 팽팽한 호적수 공방 끝에 양군이 대치하며 무승부로 회군했습니다.`, 'text-cyan-300 font-extrabold text-sm');

      alert(`🤝 [10턴 결전 무승부 (비김)!]

${reason}

▶ 영지 변동 없이 양군 모두 전력을 보존하며 회군하였습니다.
▶ 다음 전투에서 승기를 잡으십시오!`);
      closeHexBattle(false);
    }


    // ==========================================================================
    // 🛡️ [패배 및 영지 피탈 / 후퇴 시스템 전면 개편]
    // 1) 내가 먼저 공격하다 졌을 때: 원정 실패 & 본대로 안전 후퇴 (게임오버 아님!)
    // 2) 방어전에서 졌을 때: 다른 아군 영지가 남아있으면 거기로 피신/천도!
    // 3) 오직 모든 땅을 다 빼앗겼을 때만(남은 땅 0개) 비로소 천하 패망!
    // ==========================================================================
    function triggerDefeat(msg) {
      if (sam5BattleState.battleOver) return;
      sam5BattleState.battleOver = true;
      playSound('fire');
      logBattle("통한의 패배: " + msg);

      setTimeout(() => {
        closeModal('hex-battle-modal');

        const isDefense = hexBattleContext.isDefense || false;
        const targetProv = hexBattleContext.targetProv || PROVINCES[0];
        const fromProv = hexBattleContext.fromProv || getMyCapital() || PROVINCES[7];

        // ----------------------------------------------------------------------
        // Case 1: 내가 먼저 공격(원정 침공)을 나갔다가 패배한 경우
        // ➔ 전쟁 패배이지 전멸이 아님! 본거지(fromProv)로 전원 안전 후퇴!
        // ----------------------------------------------------------------------
        if (!isDefense) {
          logMessage(`🐎 [원정 퇴각] 적 영지 [${targetProv.name}] 침공 작전에서 패배하여 본거지 [${fromProv.name}]으로 전군 안전하게 후퇴했습니다.`, 'text-cyan-300 font-bold');
          
          alert(`🐎 [원정 침공 작전 실패 및 본대 후퇴]\n\n적 영지 [${targetProv.name} (${targetProv.ruler}군)] 침공 작전에서 아쉽게 패배하였습니다!\n\n하지만 아군 본거지 영지는 굳건하며, 출전했던 장수들과 부대들은 본거지 [${fromProv.name}]으로 전원 안전하게 후퇴하였습니다.\n\n군사를 훈련하고 부대 레벨을 승급시켜 전력을 재정비하십시오!`);

          gameState.selectedProvId = fromProv.id;
          closeHexBattle(false);
          renderMapPins();
          updateRightPanel(fromProv.id);
          return;
        }

        // ----------------------------------------------------------------------
        // Case 2: 적이 아군 영지로 쳐들어온 방어전에서 패배하여 영지를 빼앗긴 경우
        // ----------------------------------------------------------------------
        const lostProv = fromProv; // 공격받아 빼앗긴 영지
        const enemyRuler = (hexBattleContext.enemyProv && hexBattleContext.enemyProv.ruler) ? hexBattleContext.enemyProv.ruler : '적군';
        lostProv.ruler = enemyRuler; // 영지 피탈!

        // 남은 아군 영지 계산
        const remainingProvs = PROVINCES.filter(p => p.ruler === gameState.rulerName && p.id !== lostProv.id);

        if (remainingProvs.length > 0) {
          // 🚩 아직 다른 영지가 남아있음 ➔ 남은 영지로 군주와 장수들 피신/천도!
          const newCapital = remainingProvs[0];
          gameState.selectedProvId = newCapital.id;

          logMessage(`🚨 [영지 함락] [${lostProv.name}] 영지를 빼앗겼으나, 군주와 장수들은 남은 아군 영지 [${newCapital.name}]으로 무사히 피신하였습니다!`, 'text-yellow-300 font-black');

          alert(`🚨 [영지 피탈 및 잔여 영지로 피신]\n\n적의 침공에 밀려 아쉽게도 [${lostProv.name}] 영지를 빼앗겼습니다!\n\n하지만 군주 ${gameState.rulerName}와(과) 생존 장수들은 남은 아군 영지 [${newCapital.name}]으로 무사히 피신하였습니다.\n\n아직 아군에게 ${remainingProvs.length}개의 영지가 건재합니다! 군비를 수습하여 반드시 영토를 되찾으십시오!`);

          closeHexBattle(false);
          renderMapPins();
          updateRightPanel(newCapital.id);
          return;
        } else {
          // 💀 모든 영지를 다 빼앗겨 남은 영지가 0개일 때만 ➔ 비로소 천하 패망(게임오버)!
          triggerGameOver("보유한 모든 영지를 적에게 빼앗겨 천하통일의 대업이 영원히 저물었습니다...");
        }
      }, 700);
    }



    function logBattle(msg) {
      const logEl = document.getElementById("battleLog");
      logEl.innerText = msg;
    }

    // ==========================================================================
    // 초기 실행
    // ==========================================================================
    window.addEventListener("DOMContentLoaded", () => {
      renderBattlefield();
      deselectUnit();
    });
  


    // ==========================================================================
    // ⚔️ 군사 메뉴 핸들러 완벽 연결
    // ==========================================================================
    function executeRecruit() {
      closeAllPopups();
      const myProv = getMyCapital();
      if (!consumeActionPoint('모병')) return;
      if (myProv.gold < 300) {
        alert(`군자금이 부족합니다! (모병 비용: 금 300전 필요, 현재 보유: 금 ${myProv.gold}전)`);
        refundActionPoint();
        return;
      }
      myProv.gold -= 300;
      const recruited = 1200 + Math.floor(Math.random() * 800);
      myProv.soldiers = Math.min(80000, myProv.soldiers + recruited);
      myProv.morale = Math.max(50, (myProv.morale || 70) - 5); // 신병 모집으로 일시 사기 소폭 감소
      playSfx('recruit');
      updateRightPanel(myProv.id);
      logMessage(`⚔️ [모병 완료] 의용병 ${recruited.toLocaleString()}명을 모병하여 군세를 증강했습니다! (현재 병력: ${myProv.soldiers.toLocaleString()}명)`, 'text-yellow-300 font-bold');
      alert(`⚔️ [모병 성공]

군자금 300전을 들여 각지의 장정을 모병하였습니다!

▶ 신규 모집 병력: +${recruited.toLocaleString()}명
▶ 본거지 [${myCapitalName()}] 총 병력: ${myProv.soldiers.toLocaleString()}명`);
    }

    function executeConscription() {
      closeAllPopups();
      const myProv = getMyCapital();
      if (!consumeActionPoint('징병')) return;
      const drafted = 2500 + Math.floor(Math.random() * 1000);
      myProv.soldiers = Math.min(80000, myProv.soldiers + drafted);
      myProv.order = Math.max(30, (myProv.order || 80) - 10); // 징병으로 치안 소폭 감소
      playSfx('recruit');
      updateRightPanel(myProv.id);
      logMessage(`⚔️ [징병 실시] 영지 전역에서 장정 ${drafted.toLocaleString()}명을 강제 징병했습니다! (치안 -10)`, 'text-amber-400 font-bold');
      alert(`⚔️ [징병 완수]

영지 내 장정들을 신속히 징발하였습니다!

▶ 징집 병력: +${drafted.toLocaleString()}명
▶ 본거지 총 병력: ${myProv.soldiers.toLocaleString()}명
⚠️ 백성들의 원성으로 치안이 다소 하락했습니다.`);
    }

    function executeShipBuilding() {
      closeAllPopups();
      const myProv = getMyCapital();
      if (!consumeActionPoint('선박건조')) return;
      if (myProv.gold < 500) {
        alert("선박 건조를 위한 군비(금 500전)가 부족합니다.");
        refundActionPoint();
        return;
      }
      myProv.gold -= 500;
      myProv.ships = (myProv.ships || 10) + 5;
      playSfx('build');
      updateRightPanel(myProv.id);
      logMessage(`⛵ [선박 건조] 대형 누선 5척을 건조하여 수군 전력을 대폭 증강했습니다! (총 선박: ${myProv.ships}척)`, 'text-cyan-300 font-bold');
      alert(`⛵ [선박 건조 완수]

장강을 건널 대형 전투 누선 5척을 성공적으로 건조하였습니다!

▶ 보유 전투함선: ${myProv.ships}척
▶ 수상 전장에서 방어력과 기동력이 강화됩니다!`);
    }

    function openMoveModal() {
      closeAllPopups();
      alert("🐎 [군사 이동]\n\n아군 영지 간에 장수와 병력을 이동시킵니다. 지도에서 이동할 본거지 영지를 선택하십시오.");
    }

    function openTransportModal() {
      closeAllPopups();
      alert("🌾 [군량/군자금 수송]\n\n안전한 후방 영지에서 최전방 영지로 금과 군량을 안전하게 수송합니다.");
    }

    function myCapitalName() {
      const p = getMyCapital();
      return p ? p.name : '형주';
    }



    // ==================== 🚀 복원된 핵심 커맨드 및 조작 시스템 ====================

    // --- battleActionAttack ---
function battleActionAttack() {
      if (!battleData.targetProv) return;
      playTone(220, 0.2, 'sawtooth', 0.25);
      battleData.turn++;
      document.getElementById('battle-turn-count').innerText = `턴: ${battleData.turn} / 10`;

      const myDamage = Math.floor(Math.random() * 25) + 15;
      battleData.enemyPower = Math.max(0, battleData.enemyPower - myDamage);
      battleData.enemySoldiers = Math.floor(battleData.targetProv.soldiers * (battleData.enemyPower / 100));

      const enemyDmg = (gameState.difficulty === 'hard') ? Math.floor(Math.random() * 24) + 14 : Math.floor(Math.random() * 18) + 10;
      battleData.myPower = Math.max(0, battleData.myPower - enemyDmg);
      const myProv = getMyCapital();
      battleData.mySoldiers = Math.floor(myProv.soldiers * (battleData.myPower / 100));

      if (Math.random() < 0.35) {
        battleData.storageHp = Math.max(10, battleData.storageHp - 10);
        document.getElementById('battle-storage-pct').innerText = `${battleData.storageHp}%`;
        document.getElementById('battle-storage-bar').style.width = `${battleData.storageHp}%`;
      }

      document.getElementById('battle-enemy-power-pct').innerText = `${battleData.enemyPower}%`;
      document.getElementById('battle-enemy-bar').style.width = `${battleData.enemyPower}%`;
      document.getElementById('battle-enemy-soldiers-txt').innerText = battleData.enemySoldiers.toLocaleString();

      document.getElementById('battle-my-power-pct').innerText = `${battleData.myPower}%`;
      document.getElementById('battle-my-bar').style.width = `${battleData.myPower}%`;
      document.getElementById('battle-my-soldiers-txt').innerText = battleData.mySoldiers.toLocaleString();

      logBattleMsg(`⚔️ 아군 총공격! 적군에게 ${myDamage}% 타격 입힘 (적 병력 잔여: ${battleData.enemySoldiers.toLocaleString()})`, 'text-yellow-300');

      if (battleData.enemyPower <= 0) {
        endBattleVictory();
      } else if (battleData.myPower <= 0) {
        endBattleDefeat();
      }
    }

    // --- battleActionRaidStorage ---
function battleActionRaidStorage() {
      playTone(330, 0.2, 'sawtooth', 0.2);
      logBattleMsg(`🌾 적의 군량 수송대를 기습하여 적군 사기를 꺾었습니다!`, 'text-emerald-300 font-bold');
      battleData.enemyPower = Math.max(0, battleData.enemyPower - 20);
      document.getElementById('battle-enemy-power-pct').innerText = `${battleData.enemyPower}%`;
      document.getElementById('battle-enemy-bar').style.width = `${battleData.enemyPower}%`;
      if (battleData.enemyPower <= 0) endBattleVictory();
    }

    // --- battleActionTrap ---
function battleActionTrap() {
      playTone(440, 0.25, 'triangle', 0.2);
      const success = Math.random() < 0.75;
      if (success) {
        const dmg = Math.floor(Math.random() * 30) + 20;
        battleData.enemyPower = Math.max(0, battleData.enemyPower - dmg);
        document.getElementById('battle-enemy-power-pct').innerText = `${battleData.enemyPower}%`;
        document.getElementById('battle-enemy-bar').style.width = `${battleData.enemyPower}%`;
        logBattleMsg(`🔮 제갈량의 복병 함정 성공! 적군이 대혼란에 빠져 ${dmg}% 궤멸!`, 'text-cyan-300 font-bold');
        if (battleData.enemyPower <= 0) endBattleVictory();
      } else {
        logBattleMsg(`⚠️ 적군이 매복을 간파하고 우회하였습니다!`, 'text-orange-400');
      }
    }

    // --- battleStartOfficerDuel ---
function battleStartOfficerDuel() {
      if (!battleData.targetProv) return;
      // 일기토 모달에서 해당 적 영지 적장과 맞붙도록 설정
      openDuelSelectModal();
      const provSelect = document.getElementById('duel-enemy-prov-select');
      if (provSelect) {
        provSelect.value = battleData.targetProv.id;
        updateEnemyOfficersList();
      }
    }

    // --- clearLogs ---
function clearLogs() { document.getElementById('game-logs').innerHTML = ''; }

    // --- confirmTrade ---
function confirmTrade() {
      closeModal('merchant-modal');
      logMessage("🤝 [상인 거래] 낙양 거상과의 거래가 성사되었습니다.", 'text-yellow-300 font-bold');
    }

    // --- duelAction ---
function duelAction(type) {
      if (!duelState.inDuel) return;
      const my = duelState.myOfficer;
      const enemy = duelState.enemyOfficer;

      duelState.round++;
      document.getElementById('duel-round-badge').innerText = `제 ${duelState.round} 합`;

      const enemyWar = (gameState.difficulty === 'hard') ? enemy.war + 10 : enemy.war;
      const enemyInt = (gameState.difficulty === 'hard') ? enemy.int + 8 : enemy.int;

      const enemyActions = ['attack', 'heavy', 'defend'];
      if (enemyInt >= 70) enemyActions.push('tactic');
      const enemyChoice = enemyActions[Math.floor(Math.random() * enemyActions.length)];

      let myDmg = 0;
      let enemyDmg = 0;

      // 1. 플레이어 행동 판정
      if (type === 'quick') {
        playTone(480, 0.12, 'sawtooth', 0.2);
        const hit = Math.random() < 0.90;
        if (hit) {
          myDmg = Math.floor((my.war * 0.22) + Math.random() * 10);
          logDuel(`⚔️ [쾌속 공격] ${my.name}의 정교한 공격 적중! (${enemy.name}에게 ${myDmg} 피해)`, 'text-yellow-300 font-bold');
        } else {
          logDuel(`💨 ${my.name}의 공격을 ${enemy.name}이 쳐냈습니다!`, 'text-slate-400');
        }
      } else if (type === 'smash') {
        playTone(320, 0.25, 'sawtooth', 0.3);
        const hit = Math.random() < 0.65;
        if (hit) {
          myDmg = Math.floor((my.war * 0.45) + Math.random() * 15);
          logDuel(`⚡ [필살 일격 작렬!] ${my.name}의 혼신의 일격이 적장의 갑주를 쪼갰습니다!! (${enemy.name}에게 ${myDmg} 치명타!)`, 'text-red-400 font-black animate-pulse');
        } else {
          logDuel(`💨 [필살 실패] ${my.name}의 큰 기술이 빗나가며 틈을 보였습니다!`, 'text-orange-400');
        }
      } else if (type === 'defend') {
        playTone(600, 0.1, 'sine', 0.15);
        logDuel(`🛡️ [철벽 방어] ${my.name}이 방패와 칼날로 방어 태세를 굳혔습니다!`, 'text-cyan-300 font-bold');
      } else if (type === 'tactic') {
        playTone(720, 0.15, 'triangle', 0.2);
        const diff = my.int - enemyInt;
        const success = Math.random() * 100 < (50 + diff);
        if (success) {
          duelState.enemyConfused = true;
          myDmg = 22;
          logDuel(`🧠 [심리 도발 성공!] ${my.name}의 호통에 ${enemy.name}이 혼란에 빠졌습니다! (혼란 피해 22)`, 'text-purple-300 font-black');
        } else {
          logDuel(`🗣️ 도발 실패! ${enemy.name}이 냉소를 머금고 반격합니다.`, 'text-slate-400');
        }
      } else if (type === 'flee') {
        duelState.inDuel = false;
        logDuel(`🐎 [퇴각] ${my.name}이 말머리를 돌려 본진으로 무사히 철수했습니다.`, 'text-slate-300 font-bold');
        logMessage(`🐎 [일기토 퇴각] ${my.name}이 부상을 입지 않고 무사히 귀환했습니다.`, 'text-slate-300');
        setTimeout(() => closeModal('duel-modal'), 1200);
        return;
      }

      // 2. 적 장수 행동 판정
      if (duelState.enemyConfused) {
        logDuel(`😵 [적 혼란] ${enemy.name}은 정신이 혼미하여 행동하지 못했습니다!`, 'text-purple-400');
        duelState.enemyConfused = false;
      } else {
        if (enemyChoice === 'heavy') {
          if (type === 'defend') {
            const counter = 18;
            myDmg += counter;
            logDuel(`🛡️⚡ [완벽한 방어 & 반격!] ${my.name}이 적장의 강타를 튕겨내며 ${counter}의 반격 피해를 입혔습니다!`, 'text-emerald-300 font-black');
          } else {
            enemyDmg = Math.floor((enemyWar * 0.38) + Math.random() * 12);
            logDuel(`💥 [적장의 맹공!] ${enemy.name}의 묵직한 칼날이 들이닥쳤습니다! (${my.name}에게 ${enemyDmg} 피해)`, 'text-red-400 font-bold');
          }
        } else if (enemyChoice === 'attack') {
          if (type === 'defend') {
            enemyDmg = Math.floor(((enemyWar * 0.22) + Math.random() * 5) * 0.3);
            logDuel(`🛡️ [피해 경감] 적의 공격을 방패로 막아내어 피해를 ${enemyDmg}로 최소화했습니다.`, 'text-cyan-300');
          } else {
            enemyDmg = Math.floor((enemyWar * 0.22) + Math.random() * 8);
            logDuel(`⚔️ ${enemy.name}의 검격! (${my.name}에게 ${enemyDmg} 피해)`, 'text-slate-300');
          }
        } else if (enemyChoice === 'defend') {
          logDuel(`🛡️ ${enemy.name}이 뒤로 물러나며 방어 태세를 취했습니다.`, 'text-slate-400');
          myDmg = Math.floor(myDmg * 0.5);
        } else {
          logDuel(`🗣️ ${enemy.name}: '네놈의 목숨줄도 오늘이 끝이다!'`, 'text-red-300');
        }
      }

      duelState.enemyHp = Math.max(0, duelState.enemyHp - myDmg);
      duelState.myHp = Math.max(0, duelState.myHp - enemyDmg);

      document.getElementById('duel-enemy-hp-txt').innerText = `${duelState.enemyHp} / 100`;
      document.getElementById('duel-enemy-hp-bar').style.width = `${duelState.enemyHp}%`;
      document.getElementById('duel-my-hp-txt').innerText = `${duelState.myHp} / 100`;
      document.getElementById('duel-my-hp-bar').style.width = `${duelState.myHp}%`;

      if (duelState.enemyHp <= 0) {
        duelState.inDuel = false;
        playSfx('victory');
        logDuel(`🎉🏆 [일기토 완전 승리!] ${my.name}이 ${enemy.name}을 말 아래로 낙마시키고 생포했습니다!!`, 'text-yellow-300 font-extrabold text-sm');
        logMessage(`👑 [일기토 대승] ${my.name}이 적장 ${enemy.name}과의 결투에서 대승을 거두었습니다! (금 500전 노획)`, 'text-yellow-300 font-black');

        if (pendingInvasion) {
          const inv = pendingInvasion;
          pendingInvasion = null;
          const myProv = inv.targetProv;
          myProv.gold += 800;
          myProv.food += 5000;
          logMessage(`🎉🛡️ [침공군 완전 격퇴!] ${my.name} 장군이 쳐들어온 ${inv.attackerRuler}군의 선봉장 ${enemy.name}을 베어 적군 ${inv.invasionForce.toLocaleString()}명이 사기를 잃고 패주했습니다! (노획: 금 800전, 군량 5,000석)`, 'text-emerald-300 font-black');
          alert(`🎉🛡️ [수성 요격 대승!]

${my.name} 장군이 ${inv.attackerRuler}군의 선봉장 ${enemy.name}을 1:1 결투로 베었습니다!
지휘관을 잃은 적군 ${inv.invasionForce.toLocaleString()}명이 전의를 상실하고 패주하였습니다!

전리품: 금 800전, 군량 5,000석 노획!`);
          updateRightPanel(myProv.id);
        } else if (battleData.targetProv) {
          logMessage(`🚩 [영지 점령] 적장이 일기토에서 격파되어 적군이 총붕괴했습니다! ${battleData.targetProv.name}을 점령했습니다!`, 'text-yellow-300 font-black');
          alert(`🎉🏆 [일기토 대승리!]\n${my.name}이 적장 ${enemy.name}을 베어 적군이 총붕괴하고 패주했습니다!\n${battleData.targetProv.name}을 완전히 점령하여 아군 영지로 편입했습니다!`);
          endBattleVictory();
        } else {
          const myProv = getMyCapital();
          myProv.gold += 500;
          updateRightPanel(myProv.id);
          alert(`🎉 [일기토 승리] ${my.name}이 적장 ${enemy.name}을 격파했습니다!
적군의 사기가 곤두박질치고 군자금 500전을 전리품으로 획득했습니다!
(다음 장수를 골라 또 대결할 수 있습니다)`);
        }
        setTimeout(() => closeModal('duel-modal'), 1800);
      } else if (duelState.myHp <= 0) {
        duelState.inDuel = false;
        my.fatigue = 85; // 패배 장수 극심한 탈진
        logDuel(`💀 [패배] ${my.name}이 부상을 입고 휘하 장졸들의 호위를 받으며 긴급 철수했습니다!`, 'text-red-500 font-black');
        logMessage(`⚠️ [일기토 패배] ${my.name}이 결투 중 부상을 입고 후퇴했습니다. (탈진: 피로도 85%)`, 'text-red-400');
        
        if (pendingInvasion) {
          const inv = pendingInvasion;
          pendingInvasion = null;
          const target = inv.targetProv;
          const loss = Math.floor(target.soldiers * 0.25);
          target.soldiers = Math.max(500, target.soldiers - loss);
          target.defense = Math.max(10, target.defense - 10);
          logMessage(`⚠️ [방어선 돌파] ${my.name} 장군이 패배하여 ${inv.attackerRuler}군이 ${target.name}으로 난입했습니다! (병사 ${loss.toLocaleString()}명 손실)`, 'text-red-400 font-black');
          alert(`⚠️ [방어선 돌파!]
${my.name} 장군이 부상을 입고 후퇴하면서 ${inv.attackerRuler}군에게 수성 피해를 입었습니다!`);
          updateRightPanel(target.id);
        } else {
          alert(`⚠️ ${my.name}이 부상을 입고 후퇴했습니다! 다른 장수를 골라 재도전하십시오.`);
        }
        setTimeout(() => closeModal('duel-modal'), 1800);
      }
    }

    // --- executeAlliance ---
function executeAlliance() {
      closeAllPopups();
      const myProv = getMyCapital();
      const nonAllies = PROVINCES.filter(p => p.ruler !== gameState.rulerName && !gameState.allies.includes(p.ruler));
      if (nonAllies.length === 0) {
        alert('이미 천하의 모든 군벌과 동맹 관계이거나 적이 없습니다.');
        return;
      }
      const target = nonAllies[0];
      if (myProv.gold < 300) {
        alert('외교 동맹 예물로 금 300전이 필요합니다.');
        return;
      }
      myProv.gold -= 300;
      gameState.allies.push(target.ruler);
      playSfx('victory');
      logMessage(`🤝 [동맹 체결 성공] ${target.ruler}군과 피의 맹약을 맺었습니다! (전쟁 시 연합군 지원)`, 'text-cyan-300 font-extrabold');
      alert(`🤝 [동맹 체결]\n${target.ruler}과의 동맹이 성사되었습니다!\n이제 전장에 청색으로 표시되며 전쟁 시 연합군이 가세합니다.`);
      renderMapPins();
      updateRightPanel(myProv.id);
    }

