    // --- toggleBGM ---
function toggleBGM() {
      closeAllPopups();
      if (!gameState.audioCtx) {
        try { gameState.audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){}
      }
      gameState.bgmPlaying = !gameState.bgmPlaying;
      const statusEl = document.getElementById('bgm-status');
      const iconEl = document.getElementById('bgm-icon');

      if (gameState.bgmPlaying) {
        if (statusEl) statusEl.innerText = '재생 중';
        if (iconEl) iconEl.innerText = '🔊';
        document.getElementById('bgm-btn').className = 'px-2 py-1 text-xs font-bold rounded bg-emerald-700 hover:bg-emerald-600 text-yellow-100 border border-emerald-400 flex items-center gap-1 shadow';
        playRetroBgmLoop();
      } else {
        if (statusEl) statusEl.innerText = '정지됨';
        if (iconEl) iconEl.innerText = '🎵';
        document.getElementById('bgm-btn').className = 'px-2 py-1 text-xs font-bold rounded bg-amber-700 hover:bg-amber-600 text-yellow-100 border border-yellow-400 flex items-center gap-1 shadow';
        if (gameState.bgmTimer) { clearInterval(gameState.bgmTimer); gameState.bgmTimer = null; }
      }
    }


    function onCmdAmbushSkill() {
      if (!isMyTurn || isHexGameOver) return;
      const unit = hexBattleContext.units.find(u => u.id === selectedHexUnitId && u.side === 'player' && !u.hasActed);
      if (!unit) { alert('행동 가능한 아군 부대를 먼저 선택하십시오.'); return; }
      logMessage(`🌿 [매복 병법] ${unit.name} 부대가 숲 지형에 은밀히 매복하여 방어력을 200% 상승시키고 적을 기습합니다!`, 'text-emerald-400 font-bold');
      playSfx('build');
      unit.def *= 2;
      unit.hasActed = true;
      renderHexBattleMap();
      renderHexActionUI();
    }


    // ==================== 🎮 마우스 및 키보드 통합 컨트롤 시스템 ====================
    window.addEventListener('DOMContentLoaded', () => {
      initKeyboardAndMouseControls();
    });

    function initKeyboardAndMouseControls() {
      // 키보드 단축키 (0~9, d, w, t, c, r, m, ESC, Space, Enter)
      document.addEventListener('keydown', (e) => {
        // 인풋이나 텍스트에어리어 입력 중일 때는 제외
        if (['INPUT', 'SELECT', 'TEXTAREA'].includes(e.target.tagName)) return;

        const key = e.key;
        console.log('Keyboard Pressed:', key);

        // ESC: 모든 팝업 및 열려있는 모달 닫기
        if (key === 'Escape') {
          closeAllPopups();
          document.querySelectorAll('.modal-backdrop, [id$="-modal"]').forEach(el => {
            if (!el.classList.contains('hidden')) {
              el.classList.add('hidden');
              el.style.display = 'none';
              el.style.pointerEvents = 'none';
            }
          });
          return;
        }

        // 0: 휴양 (턴 종료 및 행동력 완충)
        if (key === '0') {
          e.preventDefault();
          executeRest();
          return;
        }

        // 1: 군사 팝업 토글
        if (key === '1') {
          e.preventDefault();
          togglePopup(null, 'popup-military');
          return;
        }

        // 2: 인사 팝업 토글
        if (key === '2') {
          e.preventDefault();
          togglePopup(null, 'popup-personnel');
          return;
        }

        // 3: 외교 팝업 토글
        if (key === '3') {
          e.preventDefault();
          togglePopup(null, 'popup-diplomacy');
          return;
        }

        // 4: 정보 모달 열기
        if (key === '4') {
          e.preventDefault();
          openInfoModal();
          return;
        }

        // 5: 개발 팝업 토글
        if (key === '5') {
          e.preventDefault();
          togglePopup(null, 'popup-develop');
          return;
        }

        // 6: 상인 팝업 토글
        if (key === '6') {
          e.preventDefault();
          togglePopup(null, 'popup-merchant');
          return;
        }

        // 7: 특별 팝업 토글
        if (key === '7') {
          e.preventDefault();
          togglePopup(null, 'popup-special');
          return;
        }

        // 8: 계략 팝업 토글
        if (key === '8') {
          e.preventDefault();
          togglePopup(null, 'popup-stratagem');
          return;
        }

        // 9: 기능 팝업 토글
        if (key === '9') {
          e.preventDefault();
          togglePopup(null, 'popup-system');
          return;
        }

        // D 또는 d: 장수 골라 1:1 결투 즉시 열기
        if (key === 'd' || key === 'D') {
          e.preventDefault();
          openDuelSelectModal();
          return;
        }

        // W 또는 w: 전쟁 모달 즉시 열기
        if (key === 'w' || key === 'W') {
          e.preventDefault();
          openWarModal();
          return;
        }

        // T 또는 t: 군사 훈련 즉시 실행
        if (key === 't' || key === 'T') {
          e.preventDefault();
          executeTraining();
          return;
        }

        // C 또는 c: 징병 실행
        if (key === 'c' || key === 'C') {
          e.preventDefault();
          executeConscription();
          return;
        }

        // R 또는 r: 모병 실행
        if (key === 'r' || key === 'R') {
          e.preventDefault();
          executeRecruit();
          return;
        }

        // M 또는 m: 배경음악 및 효과음 토글
        if (key === 'm' || key === 'M') {
          e.preventDefault();
          toggleBGM();
          return;
        }
      });
    }

    // togglePopup 함수가 이벤트 없이(null) 호출되어도 안전하게 작동하도록 보강
    const origTogglePopup = window.togglePopup || togglePopup;
    function togglePopup(e, id) {
      if (e && e.stopPropagation) e.stopPropagation();
      const popup = document.getElementById(id);
      if (!popup) return;
      const isOpen = popup.classList.contains('show');
      closeAllPopups();
      if (!isOpen) {
        popup.classList.add('show');
        playSfx('select');
      }
    }

